// NEET UG Biology: Neural control and coordination (NCERT Class 11, Chapter 21, rationalised). All questions original fibub work.
import { pick, int, choose, fmt, shuffleOpts, numOpts, g } from '../_entrance.js';

const E = ['neet'];
const items = [];
const groups = {};
let n = 0, pos = 0;
const POS = [2, 0, 3, 1];
const PFX = 'nc';
const nid = () => `${PFX}-${String(++n).padStart(3, '0')}`;
const AR = ['Both A and R are true and R is the correct explanation of A', 'Both A and R are true but R is not the correct explanation of A', 'A is true but R is false', 'A is false but R is true'];
const ST = ['Both Statement I and Statement II are correct', 'Both Statement I and Statement II are incorrect', 'Statement I is correct but Statement II is incorrect', 'Statement I is incorrect but Statement II is correct'];
function mc(level, sub, q, correct, wrongs, sol, trap, format = 'single') {
  const p = POS[pos++ % 4];
  const options = [...wrongs];
  options.splice(p, 0, correct);
  items.push({ id: nid(), type: 'mcq', level, format, exams: E, sub, q, options, answer: p, sol, ...(trap ? { trap } : {}) });
}
function asr(level, sub, A, R, ans, sol, trap) {
  items.push({ id: nid(), type: 'mcq', level, format: 'assertion', exams: E, sub, q: `<b>Assertion (A):</b> ${A}<br><b>Reason (R):</b> ${R}`, options: AR, answer: ans, sol, ...(trap ? { trap } : {}) });
}
function stm(level, sub, s1, s2, ans, sol, trap) {
  items.push({ id: nid(), type: 'mcq', level, format: 'statements', exams: E, sub, q: `<b>Statement I:</b> ${s1}<br><b>Statement II:</b> ${s2}`, options: ST, answer: ans, sol, ...(trap ? { trap } : {}) });
}
function match(level, sub, key, title, list1, list2, correct, wrongs, sol, trap) {
  groups[key] = { title, list1, list2 };
  const p = POS[pos++ % 4];
  const options = [...wrongs]; options.splice(p, 0, correct);
  items.push({ id: nid(), type: 'mcq', level, format: 'match', exams: E, sub, group: key, q: 'Match List I with List II and choose the correct code.', options, answer: p, sol, ...(trap ? { trap } : {}) });
}
function pass(key, title, passage) { groups[key] = { title, passage }; }
function pq(key, level, sub, q, correct, wrongs, sol, trap) {
  const p = POS[pos++ % 4];
  const options = [...wrongs];
  options.splice(p, 0, correct);
  items.push({ id: nid(), type: 'mcq', level, format: 'passage', exams: E, sub, group: key, q, options, answer: p, sol, ...(trap ? { trap } : {}) });
}
function cnt(level, sub, q, correct, wrongs, sol, trap) { mc(level, sub, q, correct, wrongs, sol, trap, 'statements'); }

// ---------------------------------------------------------------- Level 1
mc(1, 'neural system', 'The structural and functional unit of the neural system is the', 'neuron', ['nephron', 'neuroglial cell', 'ganglion'], 'A neuron is the cell that receives, carries and passes on nerve impulses. A nephron belongs to the kidney.');
mc(1, 'neural system', 'In Hydra, the neural system is made of', 'a network of neurons', ['a brain and a nerve cord', 'ganglia joined by a ventral cord only', 'a spinal cord'], 'Hydra has a simple nerve net spread through the body. It has no brain.');
mc(1, 'neural system', 'The central neural system (CNS) of humans includes', 'the brain and the spinal cord', ['only the brain', 'the brain and all the cranial nerves', 'the spinal cord and the spinal nerves'], 'CNS = brain + spinal cord. The nerves that join them to the body form the peripheral neural system.');
mc(1, 'neural system', 'Nerve fibres that carry impulses from tissues or organs to the CNS are called', 'afferent fibres', ['efferent fibres', 'motor fibres', 'effector fibres'], 'Afferent (sensory) fibres go toward the CNS. Efferent fibres carry commands from the CNS to the effector organs.');
mc(1, 'neural system', 'Which of these is a division of the autonomic neural system?', 'The sympathetic neural system', ['The somatic neural system', 'The afferent neural system', 'The cranial neural system'], 'The autonomic neural system has sympathetic and parasympathetic parts. It controls involuntary organs.');
mc(1, 'neuron structure', 'Nissl’s granules are found in the', 'cell body (cyton) of a neuron', ['axon terminal', 'node of Ranvier', 'myelin sheath'], 'Nissl’s granules are clusters of ribosomes and rough ER in the cyton and dendrites. They are absent from the axon.');
mc(1, 'neuron structure', 'The part of a neuron that carries impulses away from the cell body is the', 'axon', ['dendrite', 'Nissl’s granule', 'Schwann cell'], 'Dendrites bring impulses toward the cell body. The axon takes them away to the synaptic knobs.');
mc(1, 'neuron structure', 'A neuron with one axon and one dendrite is called', 'bipolar', ['unipolar', 'multipolar', 'apolar'], 'Bipolar neurons are found in the retina of the eye. Multipolar ones have two or more dendrites with one axon.');
mc(1, 'neuron structure', 'The myelin sheath around a peripheral axon is formed by', 'Schwann cells', ['astrocytes', 'neurons themselves', 'Nissl’s granules'], 'Schwann cells wrap round the axon of peripheral neurons and make the insulating myelin sheath.');
mc(1, 'neuron structure', 'The small gaps between two adjacent myelin sheaths are the', 'nodes of Ranvier', ['synaptic clefts', 'Casparian strips', 'synaptic knobs'], 'Nodes of Ranvier are the unmyelinated gaps where the axon membrane is exposed.');
mc(1, 'impulse', 'The membrane of a resting neuron is said to be', 'polarised, with the inside negative', ['depolarised, with the inside positive', 'polarised, with the inside positive', 'impermeable to all ions'], 'At rest the outer surface of the membrane is positively charged and the inner surface is negatively charged. This is the resting potential.');
mc(1, 'synapse', 'The junction between two neurons is called a', 'synapse', ['node', 'plexus', 'ganglion'], 'A synapse is where one neuron passes the impulse to the next. The two are separated by a gap or are joined electrically.');
mc(1, 'synapse', 'Which of these is a neurotransmitter?', 'Acetylcholine', ['Haemoglobin', 'Myosin', 'Insulin'], 'Acetylcholine is released at many synapses and at the neuromuscular junction.');
mc(1, 'brain', 'The three membranes that cover the brain are the', 'cranial meninges', ['pericardium', 'peritoneum', 'pleura'], 'Dura mater (outer), arachnoid (middle) and pia mater (inner) are the meninges. They protect the brain along with the skull.');
mc(1, 'brain', 'The two cerebral hemispheres are joined by a thick band of fibres called the', 'corpus callosum', ['corpora quadrigemina', 'pons', 'medulla'], 'The corpus callosum links the two hemispheres. The corpora quadrigemina are in the midbrain.');
mc(1, 'brain', 'The centre that controls body temperature, hunger and thirst is the', 'hypothalamus', ['cerebellum', 'medulla oblongata', 'pons'], 'The hypothalamus is part of the forebrain and has centres for temperature, eating and drinking.');
mc(1, 'brain', 'The centre for control of respiration and cardiovascular reflexes lies in the', 'medulla oblongata', ['cerebrum', 'thalamus', 'cerebellum'], 'The medulla also has centres for gastric secretions. It continues as the spinal cord.');
mc(1, 'brain', 'The cerebral cortex is also called', 'grey matter', ['white matter', 'brain stem', 'limbic lobe'], 'The cortex looks grey because it holds a dense mass of neuron cell bodies. Myelinated fibres below it form the white matter.');
mc(1, 'brain', 'The brain structure that keeps the body balanced and coordinates movement is the', 'cerebellum', ['cerebrum', 'thalamus', 'corpus callosum'], 'The cerebellum is a hindbrain structure with a very convoluted surface.');
mc(1, 'reflex', 'An involuntary, quick response to a stimulus, controlled by the CNS, is a', 'reflex action', ['voluntary action', 'conditioned action only', 'hormonal response'], 'A reflex is automatic. The spinal cord often handles it without waiting for the brain.');
mc(1, 'reflex', 'The pathway taken by an impulse in a reflex action is called the', 'reflex arc', ['neural loop', 'synaptic cleft', 'axon circuit'], 'A reflex arc has a receptor, a sensory neuron, the CNS, a motor neuron and an effector.');

// ---------------------------------------------------------------- Level 2
mc(2, 'neural system', 'Which is a correct difference between the neural and endocrine systems?', 'The neural system gives point-to-point quick coordination, while the endocrine system uses chemicals carried by blood', ['Both use only electrical impulses', 'The endocrine system works faster than the neural system', 'The neural system is chemical and widespread, the endocrine system is point-to-point'], 'Neurons form an organised network of point-to-point connections and act fast. Hormones are carried by blood to target organs and act more slowly and for longer.');
mc(2, 'neural system', 'The visceral neural system is the part of the peripheral neural system that', 'comprises the nerves, fibres, ganglia and plexuses that connect the CNS with the viscera and involuntary organs', ['connects the CNS to skeletal muscles only', 'is found only in the brain', 'is made only of sensory fibres'], 'The visceral (autonomic) part controls internal organs. The somatic part supplies skeletal muscles and the skin.');
mc(2, 'neural system', 'Which pair is correctly matched?', 'Somatic neural system : skeletal muscles', ['Autonomic neural system : skeletal muscles', 'Sympathetic neural system : voluntary movement', 'Afferent fibres : effector organs'], 'The somatic system relays impulses from the CNS to skeletal muscles. The autonomic one goes to involuntary organs and smooth and cardiac muscle.');
mc(2, 'neuron structure', 'Which of these is NOT a part of a typical neuron?', 'Cilia with a 9+2 pattern', ['Cell body with Nissl’s granules', 'Dendrites', 'Axon with synaptic knobs'], 'A neuron has dendrites, a cyton and an axon. Cilia are not a feature.');
mc(2, 'neuron structure', 'Synaptic vesicles are found in the', 'tips of the axon (synaptic knobs)', ['dendrite ends', 'nodes of Ranvier', 'Schwann cell nuclei'], 'The axon ends in fine branches, each ending in a swollen synaptic knob that holds vesicles filled with neurotransmitter.');
mc(2, 'neuron structure', 'Neurons found in the embryo that have only one axon and no dendrites are', 'unipolar', ['bipolar', 'multipolar', 'apolar'], 'The unipolar neuron has a cell body with one axon. It is seen in the embryonic stage.');
mc(2, 'neuron structure', 'Multipolar neurons are found in the', 'cerebral cortex', ['retina', 'embryo only', 'node of Ranvier'], 'The cerebral cortex has neurons with two or more dendrites and one axon. Bipolar ones are in the retina.');
mc(2, 'neuron structure', 'The myelinated nerve fibres are found in', 'spinal and cranial nerves', ['autonomic neural system only', 'the neural system of Hydra', 'sympathetic ganglia only'], 'Spinal and cranial nerves have myelinated fibres. Unmyelinated fibres, enclosed by Schwann cells without a myelin sheath, are common in the autonomic and somatic systems.');
mc(2, 'neuron structure', 'In an unmyelinated nerve fibre the axon is', 'enclosed by a Schwann cell that does not form a myelin sheath', ['covered by many layers of myelin', 'naked, with no covering at all', 'covered by the meninges'], 'The Schwann cell still surrounds the axon but does not wrap it in a thick myelin sheath.');
mc(2, 'resting potential', 'At rest, the axon membrane is ____ permeable to K<sup>+</sup> and ____ permeable to Na<sup>+</sup>.', 'fairly, nearly impermeable', ['not, highly', 'equally, equally', 'highly, highly'], 'K<sup>+</sup> can leak out through channels, and Na<sup>+</sup> hardly enters. The membrane is also impermeable to negatively charged proteins inside the axoplasm.');
mc(2, 'resting potential', 'The sodium-potassium pump moves', '3 Na<sup>+</sup> out and 2 K<sup>+</sup> in for each cycle', ['2 Na<sup>+</sup> out and 3 K<sup>+</sup> in', '3 Na<sup>+</sup> in and 2 K<sup>+</sup> out', '1 Na<sup>+</sup> out and 1 K<sup>+</sup> in'], 'The pump uses ATP. It sends three Na<sup>+</sup> out and takes two K<sup>+</sup> in, so the outside gains a net positive charge.');
mc(2, 'resting potential', 'The concentration of Na<sup>+</sup> in a resting neuron is', 'higher outside the axon than inside', ['higher inside than outside', 'equal on both sides', 'zero outside'], 'The fluid outside the axon has a high Na<sup>+</sup> and low K<sup>+</sup> concentration. The axoplasm has high K<sup>+</sup> and low Na<sup>+</sup>.');
mc(2, 'action potential', 'On stimulation of a resting neuron, the first change in the membrane is that it', 'becomes freely permeable to Na<sup>+</sup>', ['becomes freely permeable to K<sup>+</sup>', 'becomes impermeable to all ions', 'actively pumps Na<sup>+</sup> out faster'], 'Na<sup>+</sup> channels open and Na<sup>+</sup> rushes in. The inside turns positive and the outside negative.');
mc(2, 'action potential', 'The reversal of polarity across the membrane at the point of stimulus is called', 'depolarisation', ['repolarisation', 'hyperpolarisation of the resting state', 'synaptic delay'], 'The membrane at the site is depolarised. The electrical potential difference then is the action potential, also called the nerve impulse.');
mc(2, 'action potential', 'During repolarisation, the axon membrane', 'becomes impermeable to Na<sup>+</sup> and K<sup>+</sup> rushes out', ['becomes impermeable to K<sup>+</sup> and Na<sup>+</sup> rushes in', 'is permeable to neither ion', 'stops being a barrier to all ions'], 'Na<sup>+</sup> entry stops and K<sup>+</sup> diffuses outward. The resting potential comes back and the fibre is ready for another stimulus.');
mc(2, 'action potential', 'The electrical potential difference across the plasma membrane of an axon at the instant of impulse is called the', 'action potential', ['resting potential', 'threshold only', 'synaptic potential only'], 'Resting potential is the difference in the unstimulated state. Action potential is the difference when the neuron is active.');
mc(2, 'conduction', 'In a nerve fibre, the impulse moves from', 'the point of stimulus to the next point, as the current flows across the polarised membrane', ['the cell body to the axon only by diffusion of Na<sup>+</sup>', 'axon to dendrites by ATP', 'one node to the previous node'], 'At the site, the outer surface is negative and the inner surface positive. A current flows from the next resting region to this site on the outer surface, and in the reverse direction on the inner surface, depolarising the next point.');
mc(2, 'conduction', 'An impulse travels faster in a myelinated fibre because it', 'jumps from one node of Ranvier to the next', ['moves along the myelin sheath', 'needs no ions at all', 'is carried by the Schwann cells'], 'Depolarisation occurs only at nodes. The jumping is called saltatory conduction.');
mc(2, 'synapse', 'At an electrical synapse, the impulse', 'passes directly as current because the membranes are very close', ['is carried by neurotransmitters across a wide cleft', 'cannot pass at all', 'needs calcium-triggered vesicles'], 'Pre- and postsynaptic membranes lie very close. Current flows directly, so electrical synapses are faster than chemical ones.');
mc(2, 'synapse', 'Chemical synapses are those in which', 'the membranes of the two neurons are separated by a fluid-filled synaptic cleft', ['the membranes are fused', 'there is no neurotransmitter', 'conduction is by direct current'], 'A cleft separates pre- and postsynaptic membranes. The chemical transmitter carries the message across.');
mc(2, 'synapse', 'Arrival of an action potential at the axon terminal causes', 'synaptic vesicles to fuse with the membrane and release neurotransmitter into the cleft', ['postsynaptic neuron to release vesicles', 'the myelin sheath to dissolve', 'Na<sup>+</sup> to be pumped into the cleft'], 'The vesicles fuse with the presynaptic membrane. The released transmitter binds to receptors on the postsynaptic membrane and opens ion channels.');
mc(2, 'synapse', 'The neurotransmitter binds to', 'specific receptors on the postsynaptic membrane', ['the presynaptic vesicle membrane', 'Nissl’s granules', 'Schwann cells'], 'Binding opens ion channels, which can start a new potential that is excitatory or inhibitory.');
mc(2, 'brain', 'The three major parts of the human brain are', 'forebrain, midbrain and hindbrain', ['cerebrum, pons and cord', 'cerebellum, thalamus and cord', 'cerebrum, spinal cord and medulla'], 'Forebrain: cerebrum, thalamus, hypothalamus. Midbrain: corpora quadrigemina. Hindbrain: pons, cerebellum, medulla.');
mc(2, 'brain', 'Which of these is a part of the forebrain?', 'Thalamus', ['Pons', 'Medulla oblongata', 'Corpora quadrigemina'], 'The forebrain has the cerebrum, thalamus and hypothalamus.');
mc(2, 'brain', 'The cerebrum is divided into lobes. Which is NOT one?', 'Cerebellar lobe', ['Frontal', 'Temporal', 'Occipital'], 'The four cerebral lobes are frontal, parietal, temporal and occipital.');
mc(2, 'brain', 'Corpora quadrigemina are located in the', 'midbrain', ['forebrain', 'hindbrain', 'spinal cord'], 'The dorsal surface of the midbrain has four round lobes called corpora quadrigemina.');
mc(2, 'brain', 'The brain stem consists of', 'the midbrain, pons and medulla oblongata', ['the cerebrum, thalamus and hypothalamus', 'the cerebellum only', 'the cerebrum, pons and cerebellum'], 'The midbrain, pons and medulla together form the brain stem, which connects the brain to the spinal cord.');
mc(2, 'brain', 'The major coordinating centre for sensory and motor signalling is the', 'thalamus', ['pons', 'cerebellum', 'medulla'], 'The cerebrum wraps around the thalamus. Almost all sensory signals pass through the thalamus to the cortex.');
mc(2, 'brain', 'The pons is made mostly of', 'fibre tracts that interconnect different regions of the brain', ['cell bodies only', 'endocrine cells', 'neuroglia only'], 'Pons means bridge. It has fibres linking the cerebellum, cerebrum and medulla.');
mc(2, 'brain', 'The white matter of the brain is white because', 'it has myelinated nerve fibres', ['it has many cell bodies', 'it has no neurons at all', 'it is covered by pia mater only'], 'Myelin is whitish and fatty. The grey matter on the outside is rich in cell bodies.');
mc(2, 'brain', 'The functions of the limbic system include', 'emotional reactions, sexual behaviour and motivation', ['reading and memory only', 'control of breathing', 'balance of the body'], 'The limbic system, with the hypothalamus, regulates expression of emotions like fear and rage, sexual behaviour and motivation.');
mc(2, 'reflex', 'Which of these is a reflex action?', 'Quickly pulling your hand away from a hot pan', ['Writing your name', 'Riding a bicycle', 'Solving a sum'], 'A reflex is a fast, involuntary response. The other three need conscious thought and brain control.');
mc(2, 'reflex', 'Which order of a reflex arc is correct?', 'Receptor, afferent neuron, interneuron in CNS, efferent neuron, effector', ['Receptor, efferent neuron, CNS, afferent neuron, effector', 'Effector, afferent neuron, CNS, efferent neuron, receptor', 'Receptor, CNS, effector, afferent neuron, efferent neuron'], 'The sensory neuron carries the stimulus in, the CNS processes it and the motor neuron carries the command out to the effector.');
mc(2, 'reflex', 'In a reflex arc, the impulse from the CNS to the effector is carried by', 'efferent (motor) neurons', ['afferent neurons', 'interneurons', 'neuroglial cells'], 'Efferent neurons carry the command from the CNS to the muscle or gland.');

// ---------------------------------------------------------------- Level 3
mc(3, 'action potential', 'A neuron is bathed in a fluid with very little Na<sup>+</sup>. On stimulation it will most likely', 'fail to show a normal action potential, because there is little Na<sup>+</sup> to rush in', ['show a larger action potential', 'show repolarisation first', 'stay hyperpolarised permanently with K<sup>+</sup> entering'], 'The rising phase is Na<sup>+</sup> influx down its gradient. With almost no Na<sup>+</sup> outside the gradient is lost, so the depolarisation is small or absent.', 'Do not think the pump alone makes the spike. The spike is passive Na<sup>+</sup> flow.');
mc(3, 'action potential', 'A toxin that blocks the voltage-gated Na<sup>+</sup> channels of an axon will', 'stop the axon from generating an action potential', ['stop repolarisation only', 'make the resting potential positive', 'stop the Na<sup>+</sup>/K<sup>+</sup> pump from using ATP'], 'Without Na<sup>+</sup> entry there is no reversal of polarity at the site, so no impulse starts or spreads.', 'The resting potential itself is not changed, because it depends mostly on K<sup>+</sup> leak and the pump.');
mc(3, 'action potential', 'A drug blocks the K<sup>+</sup> channels that open after depolarisation. The axon will', 'be slow to return to its resting potential', ['not depolarise at all', 'repolarise faster', 'become impermeable to Na<sup>+</sup> at rest'], 'The fall back to resting level needs K<sup>+</sup> to flow out. Blocking it keeps the inside positive longer.');
mc(3, 'resting potential', 'The main reason the inside of a resting axon is negative is that', 'K<sup>+</sup> leaks out more readily than Na<sup>+</sup> leaks in, and large negative proteins stay inside', ['Na<sup>+</sup> leaks in more readily than K<sup>+</sup> leaks out', 'the membrane is impermeable to all ions', 'Cl<sup>-</sup> is pumped out with ATP'], 'K<sup>+</sup> is high inside and leaves through leak channels. The proteins cannot cross, so the inner face becomes negative.');
mc(3, 'resting potential', 'The Na<sup>+</sup>/K<sup>+</sup> pump helps the resting potential because it', 'removes more positive charge than it brings in and keeps the two ion gradients', ['brings in more positive charge than it removes', 'moves ions by diffusion without ATP', 'moves Na<sup>+</sup> and K<sup>+</sup> equally'], 'The 3:2 exchange makes the pump electrogenic. It also keeps Na<sup>+</sup> high outside and K<sup>+</sup> high inside.');
mc(3, 'conduction', 'In a myelinated axon, the membrane is depolarised mainly at', 'the nodes of Ranvier', ['the myelin-covered segments', 'the cell body only', 'the axon hillock only'], 'Myelin insulates. Ion exchange happens only at the nodes, so the action potential appears to jump.');
mc(3, 'conduction', 'Compared with an unmyelinated fibre of the same diameter, conduction in a myelinated fibre is', 'faster and needs less energy', ['slower and needs more energy', 'faster and needs more energy', 'the same speed, but one-way only'], 'Few ions cross the membrane (only at nodes), so less ATP is spent on restoring the gradients, and the signal moves in jumps.');
mc(3, 'conduction', 'When an impulse is moving along an axon, the region just behind the active site is briefly unable to respond. This helps because', 'it stops the impulse from going backward', ['it makes the impulse go faster', 'it lets Na<sup>+</sup> channels open again at once', 'it allows ATP to be formed'], 'The recently active region is still recovering (refractory), so the impulse moves in one direction only along the axon.', 'This is about the axon. At synapses the one-way travel has another reason.');
mc(3, 'synapse', 'Impulse transmission at a chemical synapse is one-way because', 'vesicles with neurotransmitter are only on the presynaptic side and receptors only on the postsynaptic side', ['the postsynaptic membrane has more Na<sup>+</sup> channels', 'the cleft is too wide for any signal to travel back', 'electrical current can pass only in one direction in the cleft'], 'Transmitter is released from the presynaptic knob and acts on postsynaptic receptors. Nothing is set up to release it back the other way.');
mc(3, 'synapse', 'The small delay seen in a chemical synapse is mainly due to', 'release and diffusion of the neurotransmitter and its binding to receptors', ['slow conduction in the axon', 'the closing of K<sup>+</sup> channels in the axon', 'the nodes of Ranvier'], 'Electrical synapses have no such steps, so they are faster.');
mc(3, 'synapse', 'The new potential created in the postsynaptic neuron after neurotransmitter binding can be', 'either excitatory or inhibitory', ['only excitatory', 'only inhibitory', 'only an action potential'], 'Depending on which ion channels open, the potential may push the neuron toward firing (excitatory) or away from it (inhibitory).');
mc(3, 'synapse', 'Which of these would affect a chemical synapse but NOT an electrical synapse?', 'A drug that blocks neurotransmitter receptors', ['A drug that blocks Na<sup>+</sup> channels in the axon', 'Cooling the axon', 'Damage to the myelin sheath of the axon'], 'Only a chemical synapse uses neurotransmitters and receptors. The other options act on the axon, which both synapse types have.');
mc(3, 'brain', 'A person is injured and loses the ability to coordinate voluntary movements and keep balance, but can still feel and think. The likely damage is to the', 'cerebellum', ['medulla oblongata', 'hypothalamus', 'corpus callosum'], 'The cerebellum is concerned with coordination of movement and posture. Medulla damage affects breathing and heartbeat.');
mc(3, 'brain', 'Damage to the corpus callosum would mainly', 'interrupt communication between the two cerebral hemispheres', ['stop breathing', 'block reflexes in the spinal cord', 'end body temperature control'], 'The corpus callosum is a fibre bundle between the hemispheres.');
mc(3, 'brain', 'A patient loses control of body temperature but can move normally. The structure most likely injured is the', 'hypothalamus', ['pons', 'cerebellum', 'corpora quadrigemina'], 'The hypothalamus has the thermoregulatory centre. It also has centres for hunger and thirst.');
mc(3, 'brain', 'The association areas of the cerebral cortex are', 'areas that are neither clearly sensory nor motor and handle memory, communication and intersensory association', ['areas that control only voluntary muscles', 'areas that control only vision', 'areas that are found only in the hindbrain'], 'A large part of the cortex is not directly sensory or motor. These association areas handle complex functions such as memory and language.');
mc(3, 'brain', 'The cerebral cortex has folds (gyri and sulci) because', 'they increase the surface area so that more neurons can be packed in', ['they protect the brain', 'they separate the two hemispheres', 'they carry cerebrospinal fluid only'], 'More cortex area means more cell bodies in the same skull volume.');
mc(3, 'brain', 'The cerebellum has a highly convoluted surface. This provides', 'extra space for many more neurons', ['extra space for blood only', 'more white matter than grey', 'protection from shock'], 'Like the cerebral cortex, its folding increases the surface for neuron cell bodies.');
mc(3, 'brain', 'Which of these is correct for the midbrain?', 'It lies between the thalamus/hypothalamus and the pons, and a canal called the cerebral aqueduct passes through it', ['It lies between the pons and the medulla', 'It is a part of the forebrain', 'It contains the corpus callosum'], 'The midbrain is located between the forebrain (thalamus and hypothalamus) and the pons of the hindbrain. The cerebral aqueduct passes through it.');
mc(3, 'brain', 'Choose the correct pair of meninges (outer to inner) covering the brain.', 'Dura mater, arachnoid, pia mater', ['Pia mater, arachnoid, dura mater', 'Arachnoid, dura mater, pia mater', 'Dura mater, pia mater, arachnoid'], 'The dura mater is the tough outer layer, the arachnoid is in the middle and the pia mater is thin and sits on the brain.');
mc(3, 'reflex', 'In the spinal cord, the fibres of sensory neurons enter through the ____ root and those of motor neurons leave through the ____ root.', 'dorsal, ventral', ['ventral, dorsal', 'dorsal, dorsal', 'ventral, ventral'], 'Dorsal root = sensory entry (cell bodies in the dorsal root ganglion). Ventral root = motor exit.', 'Sensory fibres enter at the back (dorsal) of the cord. Motor fibres leave at the front (ventral).');
mc(3, 'reflex', 'In a reflex arc, the integration of sensory input and motor output usually occurs in the', 'spinal cord', ['cerebral cortex', 'receptor', 'effector'], 'Many reflexes are processed in the spinal cord, so they are fast. The brain is informed later.');
mc(3, 'reflex', 'A person touches a hot object and withdraws the hand before feeling pain. This is because', 'the reflex is completed through the spinal cord while the signal to the brain takes slightly longer', ['pain receptors are absent', 'the brain does not get any signal', 'the motor neuron is faster than the sensory neuron in every case'], 'The reflex arc is short and does not wait for the brain. The brain receives the signal as well and gives the feeling of pain afterwards.');
mc(3, 'reflex', 'The knee-jerk reflex, in its simplest form, has', 'a receptor, an afferent neuron, an efferent neuron and an effector with the CNS in between', ['no CNS part at all', 'only an efferent neuron', 'a hormone as the messenger'], 'The patellar tendon stretch is detected by receptors, a sensory fibre carries the impulse to the spinal cord and a motor neuron carries the command to the thigh muscle.');
mc(3, 'neural system', 'Which is the correct classification of the peripheral neural system?', 'Afferent and efferent fibres; the efferent includes somatic and autonomic parts', ['Sympathetic and sensory only', 'Brain and spinal cord', 'Cranial and spinal cord'], 'The PNS has afferent fibres (to the CNS) and efferent fibres (from the CNS). The efferent supply is divided into somatic and autonomic.');
mc(3, 'neuron structure', 'The neuron’s protein-making machinery is in the', 'cell body', ['synaptic knob', 'node of Ranvier', 'myelin sheath'], 'Nissl’s granules (ribosomes and rough ER) in the cell body make proteins. Some of these are carried down the axon.');
mc(3, 'impulse', 'The membrane potential during rest in a typical neuron is about', '-70 mV (inside relative to outside)', ['+70 mV', '0 mV', '-7 mV'], 'The inside is negative relative to the outside, about -70 mV in many neurons. At the peak of the action potential, it reaches around +30 mV.');
mc(3, 'impulse', 'If the stimulus is too weak to depolarise the membrane to threshold, the neuron', 'does not fire', ['fires a small action potential', 'fires after a delay', 'fires an inhibitory impulse'], 'The response is all-or-none. A stimulus below threshold gives no action potential.');
mc(3, 'impulse', 'Stronger stimuli to a single axon produce', 'more frequent action potentials of the same size', ['larger action potentials', 'smaller action potentials', 'action potentials that move faster'], 'Size is fixed (all-or-none). The nervous system tells strength by the rate of firing and by how many neurons fire.', 'Many students say bigger spike. It is not.');
asr(3, 'resting potential', 'The membrane of a resting axon is polarised.', 'The outer surface of the membrane is positively charged and the inner surface is negatively charged.', 0, 'The potential difference across the membrane at rest is by definition this polarity. R states what polarised means, so it explains A.');
asr(3, 'conduction', 'A myelinated nerve fibre conducts impulses faster than an unmyelinated one of the same size.', 'In myelinated fibres the action potential is formed only at the nodes of Ranvier and the impulse jumps from node to node.', 0, 'The myelin insulates and stops ion exchange along its length. Only the nodes depolarise, so the impulse jumps. This is the reason for the speed.');
asr(3, 'synapse', 'A chemical synapse transmits the impulse in only one direction.', 'Neurotransmitter vesicles are present only in the presynaptic knob and receptors only on the postsynaptic membrane.', 0, 'The transmitter is made, stored and released on one side only, and the receptors are on the other. Therefore the signal cannot go back.');
asr(3, 'neuron structure', 'Nissl’s granules are absent from the axon.', 'Nissl’s granules are made of ribosomes and rough endoplasmic reticulum.', 1, 'Both are true. But R (what they are made of) does not give the reason they are missing from the axon; the cell body is simply the protein-making region. So R is not the explanation.', 'Two true statements need not be cause and effect.');
asr(3, 'brain', 'The cerebral cortex is called the grey matter.', 'The cerebral cortex is made mostly of myelinated nerve fibres.', 2, 'A is true: the cortex is rich in cell bodies and looks grey. R is false: myelinated fibres make the white matter, which lies beneath.');
asr(3, 'brain', 'Damage to the medulla oblongata is often fatal.', 'The medulla has the centres that control respiration and cardiovascular reflexes.', 0, 'Breathing and heartbeat rely on these centres. Loss leads to death, so R explains A.');
asr(3, 'neuron structure', 'The axon carries impulses away from the cell body.', 'Dendrites also carry impulses away from the cell body.', 2, 'A is true. R is false: dendrites carry impulses toward the cell body.');
asr(3, 'synapse', 'Impulse transmission is faster at an electrical synapse than at a chemical synapse.', 'There is no delay due to neurotransmitter release and diffusion at an electrical synapse.', 0, 'At an electrical synapse the current flows directly across closely placed membranes. No release, diffusion or binding is needed.');
asr(3, 'brain', 'The hypothalamus provides a link between the neural and endocrine systems.', 'The hypothalamus has neurosecretory cells that release hormones.', 0, 'These neurosecretory cells release hypothalamic hormones that control the pituitary, so R explains A.');
asr(3, 'reflex', 'A reflex action can take place even without the brain.', 'The spinal cord can act as the integrating centre for a reflex arc.', 0, 'A spinal reflex is completed in the spinal cord. The brain is informed but is not needed for the response.');
asr(3, 'brain', 'Corpora quadrigemina are present in the forebrain.', 'They are four round lobes present on the dorsal side.', 3, 'A is false: they are in the midbrain. R is true: there are four rounded lobes on the dorsal side of the midbrain.');
asr(3, 'impulse', 'A stronger stimulus makes a larger action potential in an axon.', 'Once the threshold is reached, the opening of Na<sup>+</sup> channels reinforces itself and the response is all-or-none.', 3, 'A is false: the action potential size is fixed. R is true and in fact is the reason A is false.');
stm(3, 'brain', 'The thalamus is the major coordinating centre for sensory and motor signalling.', 'The thalamus is a part of the hindbrain.', 2, 'The thalamus does relay sensory and motor signals. It is a part of the forebrain (the cerebrum wraps around it), so II is wrong.');
stm(3, 'brain', 'The pons is a part of the hindbrain.', 'The pons is made of fibre tracts that connect different regions of the brain.', 0, 'The hindbrain has the pons, cerebellum and medulla. The pons is a bridge of fibre tracts.');
stm(3, 'resting potential', 'At rest the axon membrane is more permeable to K<sup>+</sup> than to Na<sup>+</sup>.', 'At rest the axon membrane is permeable to negatively charged proteins in the axoplasm.', 2, 'I is right. II is wrong: the membrane is impermeable to these proteins, which is part of why the inside is negative.');
stm(3, 'synapse', 'Electrical synapses are rare in the human neural system.', 'Chemical synapses have a synaptic cleft between the membranes.', 0, 'Both are as given in NCERT. Most synapses in humans are chemical.');
stm(3, 'neuron structure', 'Dendrites have Nissl’s granules.', 'Axons have Nissl’s granules.', 2, 'Nissl’s granules are in the cell body and extend into the dendrites. They are absent in the axon.');
stm(3, 'neuron structure', 'Unmyelinated fibres are found in the autonomic and somatic neural systems.', 'Myelinated fibres are found only in the brain.', 2, 'I is correct. II is false: spinal and cranial nerves have myelinated fibres.');
stm(3, 'brain', 'The limbic system is concerned with emotional reactions.', 'The limbic system includes the cerebellum.', 2, 'I is right. The limbic system is made of the inner parts of the cerebral hemispheres, with the amygdala and hippocampus and related structures. It does not include the cerebellum.');
stm(3, 'conduction', 'Saltatory conduction occurs in myelinated fibres.', 'Saltatory conduction requires more energy than conduction in unmyelinated fibres.', 2, 'I is right. II is false: since ion exchange is limited to nodes, less ATP is needed.');
stm(3, 'reflex', 'A reflex arc always includes the brain.', 'A reflex action is an involuntary response to a stimulus.', 3, 'I is false: spinal reflexes do not need the brain. II is a correct definition.');
stm(3, 'impulse', 'An action potential is all-or-none.', 'The size of an action potential in an axon increases as the strength of the stimulus increases.', 2, 'I is right. II is false: stronger stimuli give more frequent but equal-sized impulses.');
cnt(3, 'brain', 'How many of these belong to the hindbrain: pons, thalamus, cerebellum, medulla oblongata, hypothalamus?', 'Three', ['Two', 'Four', 'Five'], 'Pons, cerebellum and medulla are hindbrain. Thalamus and hypothalamus are forebrain. So three.');
cnt(3, 'neuron structure', 'How many of these are parts of a neuron: Nissl’s granules, nodes of Ranvier, synaptic knobs, dendrites, corpus callosum?', 'Four', ['Three', 'Five', 'Two'], 'The corpus callosum is a brain structure joining the hemispheres. The other four are parts of a neuron or its sheath.');
match(3, 'brain', 'm1', 'Brain parts and functions',
  ['A. Thalamus', 'B. Hypothalamus', 'C. Cerebellum', 'D. Medulla oblongata'],
  ['p. Control of respiration', 'q. Relay of sensory and motor signals', 'r. Control of body temperature', 's. Coordination of movement and balance'],
  'A-q, B-r, C-s, D-p', ['A-r, B-q, C-s, D-p', 'A-q, B-r, C-p, D-s', 'A-s, B-r, C-q, D-p'],
  'Thalamus relays signals (q), hypothalamus holds the thermoregulation centre (r), cerebellum coordinates movement (s), medulla controls breathing (p).', 'Thalamus and hypothalamus are neighbours but do different jobs.');
match(3, 'impulse', 'm2', 'Events in a neuron',
  ['A. Resting potential', 'B. Depolarisation', 'C. Repolarisation', 'D. Na<sup>+</sup>/K<sup>+</sup> pump'],
  ['p. Efflux of K<sup>+</sup>', 'q. Inside negative, outside positive', 'r. Influx of Na<sup>+</sup>', 's. 3 Na<sup>+</sup> out and 2 K<sup>+</sup> in, using ATP'],
  'A-q, B-r, C-p, D-s', ['A-r, B-q, C-p, D-s', 'A-q, B-p, C-r, D-s', 'A-s, B-r, C-p, D-q'],
  'Resting: inside negative (q). Depolarisation: Na<sup>+</sup> rushes in (r). Repolarisation: K<sup>+</sup> leaves (p). Pump: ATP-driven 3:2 exchange (s).');
match(3, 'neuron structure', 'm3', 'Neurons and where they occur',
  ['A. Unipolar neuron', 'B. Bipolar neuron', 'C. Multipolar neuron', 'D. Myelinated fibres'],
  ['p. Cerebral cortex', 'q. Retina of the eye', 'r. Embryonic stage', 's. Spinal and cranial nerves'],
  'A-r, B-q, C-p, D-s', ['A-q, B-r, C-p, D-s', 'A-r, B-p, C-q, D-s', 'A-r, B-q, C-s, D-p'],
  'Unipolar neurons are embryonic, bipolar ones are in the retina, multipolar neurons are in the cerebral cortex and myelinated fibres are in spinal and cranial nerves.');
match(3, 'brain', 'm4', 'Structure and location',
  ['A. Corpora quadrigemina', 'B. Pons', 'C. Corpus callosum', 'D. Amygdala'],
  ['p. Connects the two cerebral hemispheres', 'q. Midbrain', 'r. Hindbrain', 's. Limbic system'],
  'A-q, B-r, C-p, D-s', ['A-r, B-q, C-p, D-s', 'A-q, B-r, C-s, D-p', 'A-p, B-r, C-q, D-s'],
  'The corpora quadrigemina are in the midbrain, the pons in the hindbrain, the corpus callosum joins the hemispheres and the amygdala belongs to the limbic system.');
{
  const it = { id: nid(), type: 'nat', level: 3, format: 'integer', exams: E, sub: 'resting potential', q: 'A Na<sup>+</sup>/K<sup>+</sup> pump in a patch of membrane works for 40 cycles. How many Na<sup>+</sup> ions are moved out of the cell?', answer: 120, tol: 0, calc: () => 40 * 3, sol: 'Each cycle pushes 3 Na<sup>+</sup> out. So 40 cycles move 40 x 3 = 120 Na<sup>+</sup> out.', trap: 'Do not use the K<sup>+</sup> number (2).' };
  items.push(it);
  items.push({ id: nid(), type: 'nat', level: 3, format: 'integer', exams: E, sub: 'resting potential', q: 'A pump works for 50 cycles. What is the net number of positive charges moved from the inside to the outside?', answer: 50, tol: 0, calc: () => 50 * 3 - 50 * 2, sol: 'Per cycle: 3 positive charges out, 2 in, so net 1 out. In 50 cycles: 50 x (3 - 2) = 50.', trap: 'Subtract, do not add: 3 out and 2 in.' });
}

// ---------------------------------------------------------------- Level 4
mc(4, 'resting potential', 'A drug stops the Na<sup>+</sup>/K<sup>+</sup> pump (no ATP use) in an axon that was just at rest. What is the best prediction?', 'The axon can still fire many impulses at first, but the gradients slowly run down and firing finally fails', ['It cannot fire even one impulse', 'It fires at once with a larger potential', 'Its resting potential at once becomes +30 mV'], 'One impulse moves only a tiny fraction of the ions, so the stored gradients last for a long time. Without the pump they are not restored and the neuron stops working after many impulses.', 'The pump does not make the spike. It keeps the gradients for later spikes.');
mc(4, 'action potential', 'In the graph of an action potential, the membrane potential rises from -70 mV to about +30 mV and then falls back. The falling part is mainly due to', 'K<sup>+</sup> moving out of the axon while Na<sup>+</sup> entry stops', ['Na<sup>+</sup> moving out by the pump', 'Na<sup>+</sup> moving in faster', 'Cl<sup>-</sup> moving out'], 'After the peak, Na<sup>+</sup> channels close and K<sup>+</sup> channels are open. K<sup>+</sup> leaves, the inside becomes negative again. The pump works over a longer time.', 'Many pick the pump, but the pump is far too slow to explain the fall.');
mc(4, 'action potential', 'At the peak of an action potential (+30 mV), which statement is correct?', 'The inside of the axon is positive relative to the outside, and Na<sup>+</sup> permeability has just begun to fall', ['The outside of the axon is positive relative to the inside', 'K<sup>+</sup> has stopped moving', 'The membrane is equally permeable to all ions'], 'At the peak, the inner face is positive. The Na<sup>+</sup> channels then close and K<sup>+</sup> efflux repolarises the fibre.');
mc(4, 'action potential', 'If the extracellular K<sup>+</sup> concentration is increased a lot, the resting potential becomes', 'less negative, as the K<sup>+</sup> gradient is smaller', ['more negative', 'exactly +30 mV', 'unchanged'], 'The negative resting value depends on K<sup>+</sup> tending to leave. Less outward gradient means less charge separation, so the inside is less negative.');
mc(4, 'conduction', 'In a disease in which the myelin of nerve fibres is damaged, the most direct effect is', 'slowed or blocked conduction of impulses', ['stopping the sodium-potassium pump', 'increase in the speed of conduction', 'permanent depolarisation of the cell body'], 'With myelin damaged, current leaks out between nodes and the jump from node to node fails. Conduction becomes slow or fails.');
mc(4, 'conduction', 'In which neurons would the saltatory conduction NOT occur?', 'Unmyelinated fibres enclosed by Schwann cells without a myelin sheath', ['Fibres of cranial nerves', 'Fibres of spinal nerves', 'Large motor fibres'], 'Saltatory conduction needs nodes of Ranvier between myelinated stretches. Unmyelinated fibres conduct continuously along the whole membrane.');
mc(4, 'conduction', 'During conduction on a stimulated axon, the flow of current on the outer surface of the membrane is', 'from the resting (positive) region toward the active (negative) site', ['from the active site toward the resting region', 'absent', 'in the same direction as on the inner surface'], 'At the active site the outside is negative. Outside, the current flows from the positive resting region to this site. Inside, it flows in the opposite direction, completing a circuit that depolarises the next stretch.');
mc(4, 'synapse', 'Removing Ca<sup>2+</sup> from the fluid around a presynaptic terminal, while the action potential still arrives, will', 'prevent neurotransmitter release', ['prevent the action potential in the axon', 'increase the release', 'make the synapse electrical'], 'Ca<sup>2+</sup> entry into the knob is what triggers the fusion of synaptic vesicles. The action potential still arrives but no transmitter is released.');
mc(4, 'synapse', 'A poison keeps acetylcholinesterase from working at a neuromuscular junction. The muscle will', 'stay stimulated, since acetylcholine is not broken down', ['relax completely', 'be unable to receive acetylcholine', 'release more acetylcholine from its own vesicles'], 'The enzyme normally clears ACh from the cleft. If it is blocked, ACh remains bound to receptors and the muscle continues to be stimulated.');
mc(4, 'synapse', 'A toxin blocks the release of acetylcholine at the neuromuscular junction. This will lead to', 'paralysis of the muscle, because the muscle gets no signal', ['continuous contraction of the muscle', 'faster conduction in the axon', 'conversion of the junction into an electrical synapse'], 'The axon conducts normally, but without ACh the muscle fibre is not stimulated, so it is paralysed.');
mc(4, 'synapse', 'A transmitter that opens ion channels letting negative ions enter the postsynaptic cell will make the cell', 'more negative inside, so it is harder to fire', ['more positive inside, so easier to fire', 'fire an action potential at once', 'unaffected'], 'Entry of negative ions (or exit of K<sup>+</sup>) pushes the inside to a more negative value, an inhibitory effect.');
mc(4, 'synapse', 'Which of these is the correct sequence at a chemical synapse?', 'Action potential at knob, vesicles fuse, transmitter enters cleft, binds receptors, postsynaptic channels open', ['Transmitter binds receptors, vesicles fuse, action potential at knob, channels open', 'Vesicles fuse, action potential at knob, channels open, transmitter binds', 'Channels open, transmitter enters cleft, action potential at knob, vesicles fuse'], 'The order follows the signal: arrival, release, diffusion, binding and response.');
mc(4, 'brain', 'The limbic system, together with the hypothalamus, is involved in', 'sexual behaviour, emotional reactions and motivation', ['balance and posture', 'respiratory reflexes', 'transmission of impulses from the cord to the cerebrum'], 'This is the NCERT statement. Balance is the cerebellum, respiratory reflexes the medulla, and the pons carries tracts.');
mc(4, 'brain', 'Which of these is NOT correct about the brain?', 'The cerebrum is a part of the hindbrain', ['The hypothalamus has neurosecretory cells', 'The pons lies between midbrain and medulla', 'The medulla is connected with the spinal cord'], 'The cerebrum is a forebrain structure. The other three statements are true.', 'Read the word NOT.');
mc(4, 'brain', 'Which part is correctly paired with its position?', 'Cerebral aqueduct : midbrain', ['Corpus callosum : hindbrain', 'Pons : forebrain', 'Thalamus : midbrain'], 'The cerebral aqueduct passes through the midbrain. The corpus callosum joins the cerebral hemispheres (forebrain), the pons is hindbrain and the thalamus is forebrain.');
mc(4, 'brain', 'A brain injury leaves a person with normal sensation and movement but with loss of memory of recent events and trouble forming emotional responses. The most likely region involved is the', 'limbic system (including the hippocampus and amygdala)', ['cerebellum', 'medulla oblongata', 'pons'], 'The hippocampus is associated with memory and the amygdala with emotions. These are in the limbic system.');
mc(4, 'brain', 'The cerebral hemispheres are described as having an outer cortex of grey matter and an inner white matter. If a bundle of fibres in the white matter is cut, the result is', 'loss of communication between the regions joined by those fibres, though their cell bodies remain intact', ['death of all cell bodies in the cortex', 'loss of myelin everywhere', 'formation of new grey matter'], 'White matter has the axons that connect regions. Cutting them breaks the connection but the cell bodies in the cortex may survive.');
mc(4, 'reflex', 'If the dorsal root of a spinal nerve is cut, the animal will', 'lose sensation from that area, but motor fibres are intact', ['lose motor function but keep sensation', 'lose both sensation and motor function', 'keep a normal reflex arc'], 'The dorsal root carries sensory fibres into the cord. Without it the sensory input is lost, so the reflex through that nerve is lost too, but the ventral (motor) root still works if stimulated.', 'Cutting a root breaks the reflex arc, yet the motor fibres are still alive.');
mc(4, 'reflex', 'If the ventral root of a spinal nerve is cut, the animal will', 'feel the stimulus but be unable to move the muscle', ['lose sensation but be able to move', 'lose both', 'show a normal withdrawal reflex'], 'Sensory fibres are intact, so the impulse still reaches the cord. The efferent path to the muscle is cut, so the muscle cannot respond.');
mc(4, 'reflex', 'The simplest reflex arc, as in the knee-jerk, contains', 'a sensory neuron that synapses directly with a motor neuron in the spinal cord', ['three interneurons only', 'only motor neurons', 'the cerebrum as the integrating centre'], 'In the stretch reflex, the sensory neuron synapses directly on the motor neuron in the spinal cord. This is why the response is so quick.');
mc(4, 'reflex', 'Which of these is true of both a reflex and a voluntary action?', 'Both involve neurons and effectors such as muscles', ['Both need the cerebral cortex', 'Both are always faster than 1 ms', 'Both are always unconscious'], 'Both use neural pathways ending at effectors. Only the voluntary action needs the cortex, and only the reflex is involuntary.');
mc(4, 'neuron structure', 'Select the incorrect statement.', 'Dendrites carry impulses away from the cell body', ['Axons end in synaptic knobs', 'Cell bodies contain Nissl’s granules', 'Schwann cells form myelin around peripheral axons'], 'Dendrites carry impulses to the cell body. All the other statements are correct.');
mc(4, 'neuron structure', 'Which of these structural features would be useful to make a neuron take input from many other neurons?', 'Many branched dendrites', ['A single long axon', 'A thick myelin sheath', 'Many nodes of Ranvier'], 'Dendrites receive signals. A multipolar neuron has many of them and so can receive many inputs.');
stm(4, 'neural system', 'The sympathetic and parasympathetic systems are divisions of the autonomic neural system.', 'The autonomic neural system carries impulses from the CNS to skeletal muscles.', 2, 'I is correct. II is wrong: the somatic system supplies skeletal muscles; the autonomic one supplies involuntary organs.');
stm(4, 'brain', 'The brain stem is formed by the midbrain, pons and medulla.', 'The cerebellum is a part of the brain stem.', 2, 'I is right. II is wrong: the cerebellum is a hindbrain structure that is not counted in the brain stem.', 'Cerebellum is in the hindbrain, but not in the brain stem.');
stm(4, 'synapse', 'At the electrical synapse the transmission is similar to the conduction along an axon.', 'Electrical synapses are the most common synapses in our neural system.', 2, 'I is true as the current flows directly. II is false: electrical synapses are rare in our system; most are chemical.');
stm(4, 'impulse', 'In the resting state, the Na<sup>+</sup> concentration is higher inside than outside.', 'The resting membrane is polarised.', 3, 'I is wrong: Na<sup>+</sup> is higher outside. II is true.');
asr(4, 'conduction', 'Impulse conduction in a myelinated axon uses less energy than in an unmyelinated axon.', 'In a myelinated axon, only the nodes of Ranvier need to restore Na<sup>+</sup> and K<sup>+</sup> gradients.', 0, 'The sheath prevents ion flow along internodes. Only small areas need their gradients restored by the pump, which saves ATP.');
asr(4, 'synapse', 'A chemical synapse is slower than an electrical synapse.', 'The cleft of a chemical synapse is filled with myelin.', 2, 'A is true. R is false: the cleft is fluid-filled, with no myelin. The delay is due to transmitter release and diffusion.');
asr(4, 'brain', 'The thalamus is called the relay centre of the brain.', 'Almost all sensory impulses pass through the thalamus before reaching the cerebral cortex.', 0, 'Because most sensory signals go through it, the thalamus acts as the major coordinating and relay centre.');
asr(4, 'reflex', 'A reflex action is fast.', 'Reflex arcs involve the cerebral cortex in the processing of the stimulus.', 2, 'A is true. R is false: most reflexes bypass the cortex, which is why they are fast.');
asr(4, 'resting potential', 'The Na<sup>+</sup>/K<sup>+</sup> pump is called electrogenic.', 'It moves three positive charges out for two positive charges in.', 0, 'The unequal exchange builds up charge difference across the membrane, so the pump itself contributes to the potential.');
pass('np1', 'Passage: recording from a squid-like axon', 'An axon is placed in a bath and a recording electrode measures the potential inside relative to outside. At rest the reading is -70 mV. A brief stimulus raises it to -55 mV and then it climbs steeply to +30 mV. It falls back to -70 mV in about 2 ms. In another experiment, the Na<sup>+</sup> concentration of the bath is lowered to a fifth and the peak reached is only +5 mV. In a third experiment a drug that blocks K<sup>+</sup> channels is added: the return to -70 mV is much slower.');
pq('np1', 4, 'action potential', 'The steep climb from -55 mV to +30 mV is explained by', 'rapid Na<sup>+</sup> entry', ['rapid K<sup>+</sup> entry', 'activity of the pump', 'Ca<sup>2+</sup> leaving the axon'], 'Lowering bath Na<sup>+</sup> reduces the peak, which shows that the rising phase is Na<sup>+</sup> influx.');
pq('np1', 4, 'action potential', 'The smaller peak when the bath had less Na<sup>+</sup> shows that', 'the size of the peak depends on the Na<sup>+</sup> gradient', ['the resting potential is set by Na<sup>+</sup> alone', 'K<sup>+</sup> causes the peak', 'the threshold is raised to +30 mV'], 'Less external Na<sup>+</sup> means a smaller driving force for entry, so the inside rises less.');
pq('np1', 4, 'action potential', 'The slow return when K<sup>+</sup> channels were blocked shows that', 'repolarisation depends on K<sup>+</sup> leaving the axon', ['repolarisation depends on Na<sup>+</sup> entering', 'the pump alone repolarises the axon', 'K<sup>+</sup> is needed for the rise to +30 mV'], 'Blocking the K<sup>+</sup> outflow slows the return to the negative resting value.');
pass('np2', 'Passage: nerve poisons at a neuromuscular junction', 'Three substances A, B and C are tested on a nerve-muscle preparation. With A, the nerve still shows action potentials, but the muscle does not contract and tests show no acetylcholine in the cleft. With B, acetylcholine is released normally, but it stays in the cleft and the muscle remains contracted. With C, acetylcholine is released and is broken down normally, yet the muscle does not contract, because the receptors on the muscle are covered.');
pq('np2', 4, 'synapse', 'Substance A most likely', 'stops release of acetylcholine from the nerve ending', ['blocks the receptors on the muscle', 'blocks the enzyme that breaks down acetylcholine', 'blocks the Na<sup>+</sup> channels in the axon'], 'The axon conducts (action potentials are normal), but no transmitter reaches the cleft, so the failure is at release.');
pq('np2', 4, 'synapse', 'Substance B most likely', 'inhibits acetylcholinesterase', ['blocks release of acetylcholine', 'blocks receptors', 'blocks Ca<sup>2+</sup> entry'], 'ACh persists and keeps stimulating the muscle, so the enzyme that removes it is inhibited.');
pq('np2', 4, 'synapse', 'Substance C most likely', 'blocks the acetylcholine receptors on the muscle', ['blocks the release of acetylcholine', 'blocks acetylcholinesterase', 'blocks axonal Na<sup>+</sup> channels'], 'Release and breakdown are normal. The receptors are covered, so the muscle does not respond.');

// ---------------------------------------------------------------- Level 5
mc(5, 'impulse', 'Which sequence correctly describes the change in the membrane potential at one point of an axon after a threshold stimulus?', 'Resting (-70 mV), depolarisation toward +30 mV, repolarisation back to the resting value', ['Resting, repolarisation, depolarisation', 'Depolarisation, resting, repolarisation', 'Resting, hyperpolarisation, repolarisation, depolarisation'], 'The order is fixed: Na<sup>+</sup> channels open (depolarisation), then close and K<sup>+</sup> leaves (repolarisation).');
mc(5, 'conduction', 'Two axons A and B have the same diameter. A is myelinated and B is not. Which is NOT expected?', 'B conducts faster than A', ['A uses less ATP per impulse than B', 'In A, action potentials appear only at the nodes', 'Damage to the myelin of A slows it down'], 'The myelinated fibre conducts faster, not the unmyelinated one. The other statements hold.', 'Read NOT.');
mc(5, 'conduction', 'A myelinated axon is cooled locally at one node so that Na<sup>+</sup> channels there are blocked. The impulse will', 'be unable to jump past that node unless the next node can still be reached by the current', ['go on unchanged', 'travel backward', 'travel faster'], 'Each node needs enough depolarising current to reach threshold. A blocked node does not regenerate the impulse, so the signal may fail depending on the distance to the next node.', 'The myelin does not remove the need for a working node.');
mc(5, 'conduction', 'In the CNS, myelin is formed by oligodendrocytes, and in the peripheral nerves by Schwann cells. Which is a correct difference?', 'One Schwann cell wraps one stretch of one axon, while one oligodendrocyte can wrap stretches of several axons', ['One oligodendrocyte wraps only one axon', 'Schwann cells form myelin in the brain', 'Oligodendrocytes form the neurilemma in peripheral nerves'], 'The oligodendrocyte extends several processes, each forming a sheath segment on a different axon. Schwann cells are in the peripheral nervous system.', 'This is detail beyond the main NCERT text, but it is asked.');
mc(5, 'synapse', 'Which feature is common to electrical and chemical synapses?', 'Both transmit impulses from one neuron to the next', ['Both have a synaptic cleft with vesicles', 'Both have a delay due to neurotransmitter diffusion', 'Both are always one-way'], 'Both pass information between neurons. Only the chemical type has vesicles, a cleft and a synaptic delay. Chemical synapses are one-way; electrical ones can pass current either way.');
mc(5, 'synapse', 'A drug mimics a neurotransmitter and binds permanently to its receptor, opening the channel. Compared with the natural transmitter, it will', 'keep the postsynaptic cell stimulated longer, because there is no breakdown or removal', ['stimulate the postsynaptic cell less', 'block release from the presynaptic cell', 'make the synapse electrical'], 'The natural transmitter is broken down or taken back. The drug is not, so it keeps the channel open.');
mc(5, 'synapse', 'In a synapse, a neuron that fires gives out transmitter that is excitatory for neuron X but inhibitory for neuron Y. The most likely reason is that', 'the receptors (and their channels) on X and Y are different', ['the transmitter is changed on the way', 'X and Y are connected by electrical synapses', 'Y has no cleft'], 'The effect depends on the postsynaptic receptor and the ion channels it controls, not on the transmitter alone.');
mc(5, 'brain', 'Which statement about the cerebrum is correct?', 'It wraps around the thalamus and has a left and a right hemisphere joined by the corpus callosum', ['It is a part of the brain stem', 'It is in the hindbrain', 'It is joined to the cord directly'], 'The cerebrum (forebrain) wraps around the thalamus; the hemispheres are joined by the corpus callosum. The brain stem is midbrain, pons and medulla.');
mc(5, 'brain', 'A drug acts only on the corpora quadrigemina. The function most likely affected is', 'reflex responses to visual and auditory stimuli', ['breathing', 'thermoregulation', 'balance'], 'The upper two lobes are associated with vision and the lower two with hearing. Breathing is in the medulla, temperature in the hypothalamus, balance in the cerebellum.', 'The detail goes beyond the bare NCERT line but is standard in NEET books.');
mc(5, 'brain', 'Choose the correct statement.', 'Cerebral cortex has the motor, sensory and association areas', ['The cerebral cortex is white matter', 'The cerebellum is part of the forebrain', 'The thalamus is a part of the hindbrain'], 'The cortex is grey matter with three types of areas: motor, sensory and association.');
mc(5, 'brain', 'Which part of the brain connects to the spinal cord?', 'Medulla oblongata', ['Pons', 'Thalamus', 'Cerebrum'], 'The medulla is the lowest part of the brain stem and continues into the spinal cord.');
mc(5, 'reflex', 'In the knee-jerk reflex, if the sensory neuron were cut, the reflex would be', 'lost, as the arc is broken at the afferent limb', ['unchanged, as the brain would take over', 'lost only if the motor neuron is cut', 'stronger'], 'The reflex needs an unbroken arc. A cut in the afferent limb stops the signal from reaching the spinal cord.');
mc(5, 'reflex', 'A reflex arc has 5 components. Which of these is NOT one of them?', 'Hormone', ['Receptor', 'Afferent neuron', 'Effector'], 'The five parts are receptor, afferent neuron, CNS (interneuron), efferent neuron and effector. A hormone is not part of the neural arc.');
cnt(5, 'mixed', 'How many of these statements are correct? (1) Nissl’s granules are in axons. (2) The cerebellum has a convoluted surface. (3) The pons is a part of the forebrain. (4) Myelinated fibres occur in spinal nerves. (5) The corpus callosum joins the two cerebral hemispheres.', 'Three', ['Two', 'Four', 'One'], '(1) false. (2) true. (3) false, pons is hindbrain. (4) true. (5) true. So 3 are correct.');
asr(5, 'conduction', 'Impulse conduction is slow in a thin unmyelinated fibre.', 'The depolarisation has to occur at every point along the membrane in sequence.', 0, 'The signal moves point by point along the whole length. In a myelinated fibre it jumps between nodes, which makes it much faster.');
asr(5, 'synapse', 'Electrical synapses can conduct impulses in both directions.', 'In an electrical synapse the neurotransmitter is released from the presynaptic neuron only.', 2, 'A is true as current flows through direct connections. R is false: electrical synapses do not use a neurotransmitter.');
stm(5, 'synapse', 'Impulse transmission across a chemical synapse involves the release of neurotransmitters from synaptic vesicles.', 'Neurotransmitter molecules enter the postsynaptic neuron and become part of its genetic material.', 2, 'I is right. II is wrong: the transmitter binds receptors on the postsynaptic membrane and does not enter the cell to become its genes.');
stm(5, 'neuron structure', 'The dorsal root ganglion has cell bodies of sensory neurons.', 'The ventral root of a spinal nerve carries efferent fibres.', 0, 'Both are correct. The dorsal root ganglion holds the cell bodies of sensory neurons, and the ventral root carries motor fibres out of the cord.');
match(5, 'reflex', 'm5', 'Reflex arc parts and their roles',
  ['A. Receptor', 'B. Afferent neuron', 'C. Interneuron', 'D. Effector'],
  ['p. Muscle or gland that responds', 'q. Detects the stimulus', 'r. Integrates in the CNS', 's. Carries impulse to the CNS'],
  'A-q, B-s, C-r, D-p', ['A-s, B-q, C-r, D-p', 'A-q, B-s, C-p, D-r', 'A-r, B-s, C-q, D-p'],
  'Receptor detects (q), afferent neuron carries toward the CNS (s), interneuron integrates (r), effector responds (p).');
pass('np3', 'Passage: three patients', 'Patient X can feel touch on her left hand, but cannot move it, and tests show the sensory nerve and the cord are normal. Patient Y breathes with great difficulty after a blow to the base of the skull, while his limbs move well. Patient Z lacks any emotional reaction to frightening stimuli, but can balance and breathe well.');
pq('np3', 5, 'brain', 'The injury in patient Y is most probably in the', 'medulla oblongata', ['cerebellum', 'thalamus', 'corpus callosum'], 'The base of the skull is close to the medulla, which has the respiratory centre.');
pq('np3', 5, 'brain', 'In patient Z, which structure might be damaged?', 'Amygdala of the limbic system', ['Pons', 'Cerebellum', 'Medulla'], 'Emotional responses such as fear are linked to the limbic system, especially the amygdala. Balance (cerebellum) and breathing (medulla) are intact.');
pq('np3', 5, 'neural system', 'In patient X the problem lies in the', 'efferent (motor) pathway to the left hand', ['afferent pathway', 'dorsal root ganglion', 'sensory area of the cortex'], 'Sensation is normal, so the afferent path is fine. The failure is at the motor part, such as the motor area or the ventral root or the efferent nerve.', 'The text says the sensory nerve and cord are normal, so the damage is in a motor part.');

// ===== EXPANSION (round 2) =====
const hm = (level, sub, q, correct, wrongs, sol, trap) => mc(level, sub, q, correct, wrongs, sol, trap, 'statements');
// ---- Level 2
mc(2, 'eye', 'The coloured part of the human eye that surrounds the pupil is the', 'iris', ['cornea', 'choroid', 'sclera'], 'The iris is the pigmented, visible coloured part. It contains muscle fibres that change the diameter of the pupil.');
mc(2, 'eye', 'The photoreceptors that work in dim light are the', 'rods', ['cones', 'bipolar cells', 'ganglion cells'], 'Rods contain the purplish-red pigment rhodopsin and are used in twilight (scotopic) vision. Cones work in bright light.');
mc(2, 'eye', 'The point of the retina from which the optic nerve and the retinal blood vessels leave the eye is called the', 'blind spot', ['fovea', 'macula lutea', 'pupil'], 'There are no photoreceptors at the blind spot, so no image is formed there.');
mc(2, 'eye', 'The transparent part of the outer fibrous layer of the eye, at the front, is the', 'cornea', ['sclera', 'iris', 'choroid'], 'The outer layer is the sclera (white, opaque) and its anterior part is the transparent cornea, which lets light in.');
mc(2, 'eye', 'The gel-like transparent fluid between the lens and the retina is the', 'vitreous humor', ['aqueous humor', 'perilymph', 'endolymph'], 'The vitreous chamber lies behind the lens and is filled with vitreous humor. Aqueous humor is in the front, between the cornea and the lens.');
mc(2, 'ear', 'The tube connecting the middle ear cavity to the pharynx is the', 'Eustachian tube', ['external auditory meatus', 'cochlea', 'round window'], 'The Eustachian tube equalises the pressure on the two sides of the ear drum.');
mc(2, 'ear', 'The three ear ossicles, from the tympanic membrane inward, are', 'malleus, incus and stapes', ['stapes, incus and malleus', 'incus, malleus and stapes', 'malleus, stapes and incus'], 'The malleus is attached to the tympanic membrane, the stapes to the oval window of the cochlea, and the incus lies between them.', 'Remember M-I-S: hammer, anvil, stirrup.');
mc(2, 'ear', 'The part of the inner ear that is concerned with hearing is the', 'cochlea', ['semicircular canal', 'utricle', 'saccule'], 'The coiled cochlea contains the organ of Corti. The vestibular apparatus (semicircular canals, utricle and saccule) is concerned with balance.');
mc(2, 'ear', 'The pinna of the external ear helps by', 'collecting the sound waves', ['equalising the pressure', 'amplifying the sound by ossicles', 'converting sound to nerve impulses'], 'The pinna collects sound waves and directs them into the external auditory meatus to the ear drum.');
mc(2, 'ear', 'The vestibular apparatus is mainly responsible for', 'the maintenance of body balance and posture', ['hearing high-pitched sounds', 'equalising pressure', 'colour vision'], 'It consists of three semicircular canals and the otolith organ (utricle and saccule); the crista and macula are its receptors.');
mc(2, 'neural system', 'The autonomic neural system carries impulses from the CNS to', 'involuntary organs and smooth muscles', ['skeletal muscles only', 'sense organs only', 'the cerebellum'], 'The somatic neural system supplies skeletal muscles; the autonomic neural system supplies the involuntary organs and smooth muscles.');
mc(2, 'brain', 'The medulla oblongata contains centres that control', 'respiration, cardiovascular reflexes and gastric secretions', ['body temperature and thirst', 'learning and memory', 'sense of balance only'], 'The medulla has centres for respiratory rhythm, cardiovascular reflexes and gastric secretion. Temperature and thirst are controlled by the hypothalamus.', 'Hypothalamus for temperature; medulla for breathing and heart.');
mc(2, 'eye', 'Cones are mainly responsible for', 'daylight and colour vision', ['night vision', 'detecting touch', 'secretion of aqueous humor'], 'Cones contain photopigments and work in bright light; three types (red, green and blue sensitive) give colour vision.');

// ---- Level 3
mc(3, 'eye', 'The photopigment rhodopsin is made of', 'opsin protein and retinal, a derivative of vitamin A', ['opsin and chlorophyll', 'retinal and cellulose', 'opsin and a derivative of vitamin C'], 'The visual purple, rhodopsin, has the protein opsin and retinal, which is derived from vitamin A. Shortage of vitamin A leads to night blindness.');
mc(3, 'eye', 'A person with a lack of vitamin A in the diet would first show', 'poor vision in dim light', ['loss of colour vision in daylight', 'a blind spot in each eye', 'loss of hearing'], 'Rhodopsin needs a vitamin A derivative. Without it the rods work poorly, so dim light vision (night vision) is first impaired.');
mc(3, 'eye', 'The region of the retina that gives the sharpest vision is the', 'fovea centralis, a pit in the macula lutea containing only cones', ['blind spot, containing only rods', 'ciliary body, containing cones and rods equally', 'choroid, containing bipolar cells'], 'The macula lutea has a yellowish pigment and lies at the posterior pole of the eye. At its centre, the fovea has the highest density of cones and the best resolution.', 'Blind spot has no photoreceptors.');
mc(3, 'eye', 'The middle layer of the eye, rich in blood vessels and bluish in appearance, is the', 'choroid', ['sclera', 'retina', 'cornea'], 'The choroid is the vascular middle layer. In front it forms the ciliary body and the iris.');
mc(3, 'eye', 'The lens of the eye is held in position by', 'ligaments attached to the ciliary body', ['the iris muscles', 'the sclera directly', 'the vitreous humor'], 'The ligaments (suspensory) connect the lens to the ciliary body. The lens divides the eye into aqueous and vitreous chambers.');
mc(3, 'eye', 'The three layers of cells in the retina, from the inside (towards the vitreous) to the outside, are', 'ganglion cells, bipolar cells and photoreceptor cells', ['photoreceptor cells, bipolar cells and ganglion cells', 'bipolar cells, ganglion cells and photoreceptor cells', 'ganglion cells, photoreceptor cells and bipolar cells'], 'The order is ganglion, bipolar, photoreceptor (rods and cones).', 'The signal travels from the photoreceptors to the ganglion cells, which is the reverse of this listing.');
mc(3, 'eye', 'The size of the pupil is regulated by', 'the muscle fibres of the iris', ['the ciliary body only', 'the retina', 'the aqueous humor'], 'The pupil is the opening in the iris. Its diameter is adjusted by muscle fibres in the iris.');
mc(3, 'eye', 'On exposure to light, in a rod the first change in the photopigment is', 'dissociation of retinal from opsin', ['joining of retinal to cellulose', 'formation of chlorophyll', 'breakdown of the lens protein'], 'Light causes retinal to separate from opsin. The change in opsin alters the membrane permeability and generates a potential difference in the photoreceptor.');
mc(3, 'eye', 'Equal stimulation of the three types of cones gives the sensation of', 'white light', ['black', 'red only', 'no sensation'], 'The three cone types contain photopigments sensitive to red, green and blue light. Various combinations give colours; equal stimulation gives white.');
mc(3, 'eye', 'Which structure of the eye contains a thin watery fluid?', 'The aqueous chamber, between the cornea and the lens', ['The vitreous chamber, behind the lens', 'The space between the sclera and choroid', 'The optic nerve sheath'], 'The aqueous chamber lies between the cornea and the lens and contains aqueous humor.');
mc(3, 'ear', 'The tympanic membrane (ear drum) is made of', 'connective tissue covered with skin outside and mucus membrane inside', ['cartilage covered with cuticle', 'bone covered with endothelium', 'muscle covered with mucus on both sides'], 'The ear drum separates the external and middle ears.');
mc(3, 'ear', 'The function of the ear ossicles is to', 'increase the efficiency of transmission of sound waves to the inner ear', ['collect sound waves', 'equalise pressure on the two sides of the ear drum', 'convert vibrations into nerve impulses'], 'The ossicles amplify the pressure and transmit it to the oval window of the cochlea. The pinna collects; the Eustachian tube equalises; the hair cells generate impulses.');
mc(3, 'ear', 'The membranous labyrinth is filled with', 'endolymph', ['perilymph', 'aqueous humor', 'cerebrospinal fluid only'], 'The fluid-filled membranous labyrinth contains endolymph. The space between the bony and membranous labyrinths holds perilymph.', 'Peri- means around; the membranous labyrinth is surrounded by perilymph.');
mc(3, 'ear', 'The scala media of the cochlea contains', 'endolymph', ['perilymph', 'air', 'blood'], 'The scala vestibuli and scala tympani contain perilymph; the scala media between them contains endolymph.');
mc(3, 'ear', 'The scala vestibuli ends at the', 'oval window', ['round window', 'Eustachian opening', 'tympanic membrane'], 'The scala vestibuli ends at the oval window and the scala tympani ends at the round window, which opens into the middle ear.');
mc(3, 'ear', 'The organ of Corti lies on the', 'basilar membrane', ['tectorial membrane', 'Reissner membrane', 'tympanic membrane'], 'It is a structure on the basilar membrane that contains hair cells acting as auditory receptors. The tectorial membrane lies above the hair cells.');
mc(3, 'ear', 'The thin elastic membrane above the rows of hair cells in the organ of Corti is the', 'tectorial membrane', ['basilar membrane', 'Reissner membrane', 'oval window'], 'Hair cell stereocilia press against the tectorial membrane when the basilar membrane vibrates.');
mc(3, 'ear', 'The receptors of the otolith organ (utricle and saccule) are located on a ridge called the', 'macula', ['crista ampullaris', 'organ of Corti', 'fovea'], 'The macula of utricle and saccule and the crista ampullaris of the semicircular canals are the specific receptors for balance and posture.', 'Do not confuse macula lutea of the eye with macula of the ear.');
mc(3, 'ear', 'The swollen base of each semicircular canal is called the', 'ampulla, which has the crista ampullaris', ['cochlea, which has the macula', 'utricle, which has the crista', 'saccule, which has the tectorial membrane'], 'The ampulla has a projecting ridge, the crista ampullaris, with hair cells.');
mc(3, 'ear', 'The three semicircular canals lie', 'in different planes, at right angles to one another', ['in the same plane, parallel', 'inside the cochlea', 'in the middle ear'], 'Each canal lies in a different plane at right angles to the others, so movement in any direction can be sensed.');
mc(3, 'ear', 'Nerve impulses from the hair cells of the cochlea are carried to the brain by the', 'auditory nerve to the auditory cortex', ['optic nerve to the visual cortex', 'spinal nerve to the cerebellum', 'vagus to the hypothalamus only'], 'Afferent fibres in contact with the base of hair cells carry impulses along the auditory nerve to the auditory cortex.');
mc(3, 'neural system', 'The sympathetic and parasympathetic systems are the two divisions of the', 'autonomic neural system', ['somatic neural system', 'central neural system', 'afferent division only'], 'The autonomic neural system, which supplies involuntary organs and smooth muscles, is divided into sympathetic and parasympathetic parts.');
mc(3, 'brain', 'The brain stem is formed of the', 'midbrain, pons and medulla oblongata', ['cerebrum, thalamus and hypothalamus', 'cerebellum, pons and thalamus', 'medulla, cerebellum and cerebrum'], 'The brain stem connects the brain to the spinal cord and is formed of the midbrain, the pons and the medulla.');
mc(3, 'brain', 'The thalamus is described as', 'a major coordinating centre for sensory and motor signalling', ['the centre for body temperature only', 'the seat of respiration', 'a fibre tract joining the two hemispheres'], 'The cerebrum wraps around the thalamus. The hypothalamus lies at its base and controls temperature and hunger. The corpus callosum joins the hemispheres.');
mc(3, 'neuron structure', 'Neurons with one axon and two or more dendrites, found in the cerebral cortex, are', 'multipolar', ['bipolar', 'unipolar', 'apolar'], 'Multipolar neurons are common in the cerebral cortex. Bipolar neurons have one axon and one dendrite and occur in the retina. Unipolar neurons, with one axon only, are usually seen in the embryonic stage.');
asr(3, 'eye', 'There is no vision at the blind spot of the retina.', 'The blind spot has no rods or cones.', 0, 'The optic nerve and blood vessels leave there, and no photoreceptors are present, so light falling on it does not produce a signal. R explains A.');
asr(3, 'eye', 'Rods help us see in dim light.', 'Rods contain the pigment rhodopsin, which is very sensitive to light.', 0, 'Rhodopsin (visual purple) responds even to a small amount of light, so rods can work in twilight. R explains A.');
asr(3, 'ear', 'Pressure on the two sides of the ear drum is kept equal.', 'The Eustachian tube connects the middle ear with the pharynx.', 0, 'Air passes through the tube, balancing pressure. R explains A.');
asr(3, 'ear', 'The hair cells of the organ of Corti are the auditory receptors.', 'Their stereocilia are bent against the tectorial membrane when the basilar membrane moves.', 0, 'The bending produces impulses in the associated afferent neurons. R explains A.');
asr(3, 'eye', 'Cones give colour vision.', 'There are three types of cones with different photopigments.', 0, 'Different photopigments are sensitive to red, green and blue light. Combinations produce colours.');
stm(3, 'ear', 'The perilymph fills the scala vestibuli and scala tympani.', 'The scala media contains endolymph.', 0, 'Both are correct. The scala media is within the membranous labyrinth.');
stm(3, 'eye', 'The aqueous humor lies between the cornea and the lens.', 'The vitreous humor lies between the lens and the sclera.', 2, 'Statement I is correct. Statement II is wrong: the vitreous humor fills the space between the lens and the retina.');
stm(3, 'eye', 'The macula lutea has a yellowish pigment.', 'The fovea is a thin pit in the macula, with only rods.', 2, 'Statement I is correct. Statement II is wrong: the fovea has only cones, where resolution is the highest.');
hm(3, 'ear', 'Consider these statements about the human ear. (1) The Eustachian tube opens into the pharynx. (2) The malleus is attached to the oval window. (3) The round window opens into the middle ear. (4) The scala tympani ends at the round window. How many are correct?', 'Only three', ['Only two', 'All four', 'Only one'], '(1), (3) and (4) are correct. (2) is wrong: the malleus is attached to the tympanic membrane; the stapes is attached to the oval window.', 'Malleus to drum, stapes to oval window.');
hm(3, 'eye', 'Consider these structures of the eye. (1) Sclera (2) Choroid (3) Retina (4) Aqueous chamber. How many are LAYERS of the eyeball wall?', 'Three', ['Two', 'One', 'All four'], 'The wall has three layers: outer sclera (with cornea), middle choroid (with ciliary body and iris), and inner retina. The aqueous chamber is a cavity, not a layer.', 'A chamber is a space, not a coat.');
match(3, 'eye', 'xm1', 'Part of the eye and a feature', ['A. Sclera', 'B. Choroid', 'C. Retina', 'D. Iris'], ['p. Contains blood vessels', 'q. Pigmented, controls the size of the pupil', 'r. Contains rods and cones', 's. Dense connective tissue forming the outer coat'], 'A-s, B-p, C-r, D-q', ['A-p, B-s, C-r, D-q', 'A-s, B-p, C-q, D-r', 'A-r, B-p, C-s, D-q'], 'Sclera: outer fibrous coat. Choroid: vascular layer. Retina: photoreceptors. Iris: pigmented and controls pupil diameter.');
match(3, 'ear', 'xm2', 'Part of the ear and function', ['A. Pinna', 'B. Eustachian tube', 'C. Ear ossicles', 'D. Cochlea'], ['p. Collects sound waves', 'q. Equalises pressure', 'r. Amplify and transmit sound to the inner ear', 's. Contains the organ of Corti'], 'A-p, B-q, C-r, D-s', ['A-q, B-p, C-r, D-s', 'A-p, B-q, C-s, D-r', 'A-r, B-q, C-p, D-s'], 'The pinna collects; the Eustachian tube equalises pressure; the ossicles transmit; the cochlea has the organ of Corti.');
match(3, 'ear', 'xm3', 'Structure of the ear and the fluid it holds', ['A. Membranous labyrinth', 'B. Space between bony and membranous labyrinths', 'C. Scala media', 'D. Scala tympani'], ['p. Endolymph', 'q. Perilymph', 'r. Air', 's. Aqueous humor'], 'A-p, B-q, C-p, D-q', ['A-q, B-p, C-p, D-q', 'A-p, B-q, C-q, D-p', 'A-p, B-q, C-r, D-q'], 'Membranous labyrinth and scala media: endolymph. The perilymph is in the bony labyrinth around it, including the scala tympani and scala vestibuli.', 'One option can match two entries.');

// ---- Level 4
mc(4, 'eye', 'A person has damaged cones in both eyes but healthy rods. Which would be most affected?', 'Colour vision and sharp vision in bright light', ['Vision in dim light', 'The sense of balance', 'The size of the pupil only'], 'Cones are concentrated in the fovea and give colour and high-resolution daylight vision. Rods remain to give dim-light vision.');
mc(4, 'eye', 'A scientist shines a small spot of light so that its image falls exactly on the blind spot. The person will', 'not see the spot, since there are no photoreceptors there', ['see it very sharply', 'see it only in colour', 'see it only in black and white'], 'The optic disc has no rods or cones, so no impulse is generated.');
mc(4, 'eye', 'The correct order of the path of light entering the eye to the photoreceptors is', 'cornea, aqueous humor, lens, vitreous humor, retina', ['cornea, vitreous humor, lens, aqueous humor, retina', 'lens, cornea, aqueous humor, vitreous humor, retina', 'aqueous humor, cornea, vitreous humor, lens, retina'], 'Light passes through the cornea, aqueous humor, pupil and lens, then vitreous humor, to reach the retina.');
mc(4, 'eye', 'The path of the signal in the retina after the photoreceptor is activated is', 'bipolar cells to ganglion cells to optic nerve to visual cortex', ['ganglion cells to bipolar cells to optic nerve', 'optic nerve to ganglion cells to bipolar cells', 'bipolar cells to visual cortex to ganglion cells'], 'The signal is carried from photoreceptors via bipolar cells to ganglion cells; action potentials leave in the optic nerves to the visual cortex.');
mc(4, 'eye', 'Which of the following correctly orders the events in the rod when light strikes it?', 'Retinal separates from opsin, opsin changes shape, membrane permeability changes, potential difference arises', ['Membrane permeability changes, retinal separates, potential arises, opsin changes shape', 'Potential arises, opsin changes shape, retinal separates, permeability changes', 'Opsin changes shape, potential arises, permeability changes, retinal separates'], 'Dissociation of retinal from opsin is the first step; the change in opsin alters membrane permeability, producing a potential difference.');
mc(4, 'eye', 'Which of the following statements about the human retina is NOT correct?', 'The fovea contains mostly rods and gives the best night vision', ['The macula lutea lies lateral to the blind spot', 'The blind spot has neither rods nor cones', 'Cones are most concentrated in the fovea'], 'The fovea has cones only and gives the highest resolution in daylight. Rods are more in the periphery.', 'The best acuity is not the best night vision.');
mc(4, 'ear', 'The sequence of events in hearing, from the ear drum onward, is', 'ear drum, ossicles, oval window, cochlear fluid, basilar membrane, hair cells, auditory nerve', ['ear drum, oval window, ossicles, basilar membrane, hair cells, auditory nerve', 'ossicles, ear drum, cochlear fluid, oval window, hair cells, auditory nerve', 'ear drum, ossicles, hair cells, basilar membrane, oval window, auditory nerve'], 'Sound waves vibrate the ear drum. Ossicles amplify and pass the vibrations to the oval window, setting the cochlear fluid and basilar membrane in motion. Hair cells bend against the tectorial membrane and generate impulses in the auditory nerve.');
mc(4, 'ear', 'Blockage of the Eustachian tube for a long time is most likely to cause', 'a difference in pressure on the two sides of the ear drum, and a reduction in hearing', ['loss of colour sense', 'loss of balance only', 'total absence of endolymph'], 'The tube equalises pressure. If blocked, pressure changes in the middle ear pull or push the drum and reduce its movement.');
mc(4, 'ear', 'A person has a disease in which the stapes is fixed to the oval window. Hearing is reduced because', 'vibrations are not transmitted well to the fluid of the cochlea', ['the pinna cannot collect sound', 'the hair cells are missing', 'the Eustachian tube is open'], 'The stapes passes the vibrations to the oval window. If it is fixed, the transmission of pressure to the cochlear fluid is poor.');
mc(4, 'ear', 'A drug destroys the hair cells of the organ of Corti. The effect is that', 'sound is not converted to nerve impulses, so the person is deaf', ['sound cannot enter the external ear', 'the ear drum does not vibrate', 'balance is lost completely'], 'Hair cells are the receptors that convert the movement of the basilar membrane to impulses in the afferent neurons.');
mc(4, 'ear', 'A person has damage to the crista ampullaris of the semicircular canals. Which function is mainly affected?', 'Sensing of the head rotation and balance', ['Hearing of high notes', 'Colour vision', 'Taste'], 'The crista is a receptor for dynamic balance and posture; the macula senses linear position and gravity.');
mc(4, 'ear', 'Which of the following spaces contains NO perilymph?', 'The scala media', ['The scala vestibuli', 'The scala tympani', 'The space between the bony and membranous labyrinths'], 'The scala media lies within the membranous labyrinth and holds endolymph. The other three spaces hold perilymph.');
mc(4, 'ear', 'Which of the following correctly describes the position of the organ of Corti relative to the membranes of the cochlea?', 'It lies on the basilar membrane within the scala media, below the tectorial membrane', ['It lies on the tectorial membrane within the scala tympani', 'It lies on the oval window above the scala vestibuli', 'It lies on the round window within the scala vestibuli'], 'The organ of Corti sits on the basilar membrane, and the tectorial membrane lies over the hair cells.');
mc(4, 'neural system', 'In one cycle, the Na+/K+ pump moves 3 Na+ out and 2 K+ in. After 10 cycles the net number of positive charges moved out of the cell is', '10', ['5', '50', '30'], 'Per cycle, 3 positive charges leave and 2 enter: net +1 out. After 10 cycles: 10.', 'Net charge per cycle is 3 - 2 = 1.');
mc(4, 'neuron structure', 'In which pair is the type of neuron and its site correctly matched?', 'Bipolar neuron : retina of the eye', ['Multipolar neuron : retina of the eye', 'Unipolar neuron : cerebral cortex of an adult', 'Multipolar neuron : embryonic stage only'], 'Bipolar neurons (one axon and one dendrite) are found in the retina, multipolar neurons in the cerebral cortex, unipolar mainly in the embryo.');
mc(4, 'brain', 'The hypothalamus is NOT directly concerned with', 'fine coordination of voluntary muscular movements', ['body temperature', 'hunger and thirst', 'secretion of neurohormones'], 'The cerebellum coordinates muscular movements. The hypothalamus has centres for temperature, hunger, thirst, and secretes releasing hormones.');
mc(4, 'brain', 'Which pair is correctly matched?', 'Pons : fibre tracts interconnecting different regions of the brain', ['Cerebellum : controls thirst', 'Medulla : seat of learning and memory', 'Thalamus : respiratory rhythm'], 'The pons has fibre tracts that interconnect regions of the brain. The cerebellum has convoluted surface for coordination; the medulla controls respiration and reflexes.');
mc(4, 'brain', 'The limbic system includes the amygdala, the hippocampus and', 'the inner part of the cerebral hemisphere, working with the hypothalamus in emotion and motivation', ['the cerebellum, working with the thalamus in balance', 'the pons, working with the medulla in respiration', 'the spinal cord, working with the meninges in reflexes'], 'The limbic system (limbic lobe) together with the hypothalamus regulates sexual behaviour, emotional reactions and motivation.');
mc(4, 'impulse', 'All-or-none response of an axon means that', 'once the stimulus reaches the threshold, the action potential has a fixed size independent of the stimulus strength', ['a stronger stimulus gives a larger action potential', 'weaker stimuli give smaller action potentials', 'the axon does not respond to any stimulus'], 'Action potentials do not vary in amplitude with the stimulus above the threshold. A stronger stimulus increases their frequency, not size.');
mc(4, 'conduction', 'Which feature makes conduction in a myelinated nerve fibre faster than in an unmyelinated one of the same diameter?', 'Depolarisation at the nodes of Ranvier only (saltatory conduction)', ['Larger resting potential', 'Higher concentration of Na+ outside the axon', 'A larger number of synapses'], 'Myelin is an insulating sheath. The impulse jumps from node to node, which is faster and saves energy.');
mc(4, 'synapse', 'A neurotransmitter is released from the presynaptic neuron when', 'the action potential reaches the axon terminal and synaptic vesicles fuse with the membrane', ['the postsynaptic cell becomes hyperpolarised', 'the myelin sheath breaks down', 'the Na+/K+ pump is blocked'], 'Arrival of the impulse causes synaptic vesicles to fuse with the presynaptic membrane and release the transmitter into the synaptic cleft.');
mc(4, 'reflex', 'In the reflex arc, which sequence is correct?', 'Receptor, afferent neuron, spinal cord (CNS), efferent neuron, effector', ['Receptor, efferent neuron, CNS, afferent neuron, effector', 'Effector, afferent neuron, CNS, efferent neuron, receptor', 'Receptor, afferent neuron, effector, CNS, efferent neuron'], 'Afferent fibres carry the impulse to the CNS; the efferent fibres carry the response to the effector.');
asr(4, 'eye', 'The fovea centralis gives the greatest visual resolution.', 'The fovea has the highest density of cones.', 0, 'The fovea has only cones, each connected to its own pathway. R explains A.');
asr(4, 'ear', 'The otolith organ helps to detect the position of the head relative to gravity.', 'It consists of the saccule and utricle, with receptors called macula.', 0, 'The macula of utricle and saccule senses head position. R is a description of the organ with its receptors and explains the sensing.');
asr(4, 'eye', 'Aqueous humor is found in the chamber behind the lens.', 'The vitreous humor is a transparent gel.', 3, 'A is false: the aqueous humor is between the cornea and lens. R is true.');
stm(4, 'ear', 'The oval window is connected with the stapes.', 'The round window opens into the middle ear.', 0, 'Both are correct. The stapes fits against the oval window; the scala tympani ends at the round window opening to the middle ear.');
stm(4, 'eye', 'Rods contain the pigment iodopsin.', 'Cones contain rhodopsin.', 1, 'Both are wrong: rods contain rhodopsin and cones contain iodopsin.', 'Both are swapped.');
stm(4, 'ear', 'The crista ampullaris is the receptor of the semicircular canals.', 'The macula is the receptor of the cochlea.', 2, 'Statement I is correct. Statement II is wrong: the macula is in the utricle and saccule; the cochlear receptor is the organ of Corti.');
hm(4, 'eye', 'Consider these statements. (1) Rods are active in twilight vision. (2) The three types of cones give colour vision. (3) The fovea is rich in rods. (4) The retina has three layers of cells. How many are correct?', 'Only three', ['Only two', 'All four', 'Only one'], '(1), (2) and (4) are correct. (3) is wrong: the fovea has only cones.');
hm(4, 'neural system', 'Consider these statements about the neural system. (1) The sympathetic and parasympathetic divisions make up the autonomic system. (2) Afferent fibres carry impulses from the CNS to the tissues. (3) The CNS is the brain and spinal cord. (4) The somatic system supplies skeletal muscles. How many are correct?', 'Only three', ['Only two', 'All four', 'Only one'], '(1), (3) and (4) are correct. (2) is wrong: afferent fibres carry impulses to the CNS; efferent fibres carry them from the CNS.');
match(4, 'ear', 'xm4', 'Receptor and the part of the body it senses', ['A. Organ of Corti', 'B. Crista ampullaris', 'C. Macula of utricle', 'D. Rods'], ['p. Sound', 'q. Rotation of head', 'r. Position of head against gravity', 's. Dim light'], 'A-p, B-q, C-r, D-s', ['A-q, B-p, C-r, D-s', 'A-p, B-q, C-s, D-r', 'A-p, B-r, C-q, D-s'], 'Organ of Corti: hearing. Crista: head rotation. Macula: static position. Rods: dim light.');
match(4, 'brain', 'xm5', 'Part of brain and function', ['A. Medulla oblongata', 'B. Hypothalamus', 'C. Thalamus', 'D. Corpus callosum'], ['p. Respiratory rhythm and cardiovascular reflexes', 'q. Temperature, hunger and thirst', 'r. Coordination of sensory and motor signals', 's. Connects the two cerebral hemispheres'], 'A-p, B-q, C-r, D-s', ['A-q, B-p, C-r, D-s', 'A-p, B-q, C-s, D-r', 'A-r, B-q, C-p, D-s'], 'Medulla: respiration and heart reflexes. Hypothalamus: temperature, hunger, thirst. Thalamus: relay. Corpus callosum: tract joining hemispheres.');
match(4, 'eye', 'xm6', 'Eye structure and a distinguishing feature', ['A. Macula lutea', 'B. Fovea', 'C. Blind spot', 'D. Pupil'], ['p. No photoreceptors', 'q. Yellowish pigmentation at the posterior pole', 'r. Thin pit with only cones', 's. Opening in the iris'], 'A-q, B-r, C-p, D-s', ['A-r, B-q, C-p, D-s', 'A-q, B-r, C-s, D-p', 'A-p, B-r, C-q, D-s'], 'Macula lutea: yellowish. Fovea: central thin pit with cones. Blind spot: no photoreceptors. Pupil: opening in the iris.');
match(4, 'ear', 'xm7', 'Ear structure and the structure it connects or contains', ['A. Malleus', 'B. Stapes', 'C. Scala tympani', 'D. Utricle'], ['p. Attached to the ear drum', 'q. Attached to the oval window', 'r. Ends at the round window', 's. Contains the macula'], 'A-p, B-q, C-r, D-s', ['A-q, B-p, C-r, D-s', 'A-p, B-q, C-s, D-r', 'A-p, B-r, C-q, D-s'], 'Malleus meets the drum; stapes meets the oval window; scala tympani ends at the round window; utricle has a macula.');
pass('xp1', 'Passage: a visit to the eye clinic', 'A patient says that she has trouble seeing in a dim room but sees colours and fine print well in daylight. The doctor examines the retina and finds that the photoreceptors that contain a vitamin A derivative are not working properly. Her optic disc and macula look normal.');
pq('xp1', 3, 'eye', 'The photoreceptors that are not working properly are', 'rods', ['cones', 'ganglion cells', 'bipolar cells'], 'Rods contain rhodopsin (opsin + retinal, from vitamin A) and are used in dim light.');
pq('xp1', 4, 'eye', 'The most likely cause is a deficiency of', 'vitamin A', ['vitamin C', 'vitamin K', 'vitamin D'], 'Retinal is a vitamin A derivative; lack of it reduces rhodopsin, so night vision suffers.');
pq('xp1', 4, 'eye', 'Her good daylight vision with fine print is explained by', 'normal cones in the macula and fovea', ['normal rods in the fovea', 'a normal blind spot', 'normal vitreous humor only'], 'Cones, concentrated in the fovea, are responsible for high-resolution and colour vision in bright light.');
pass('xp2', 'Passage: the hearing pathway', 'In an experiment on the ear of a mammal, a thin probe senses the movement of different membranes as a pure tone is played. The probe records vibrations of the ear drum, of three small bones in a chain, of a membrane at the entrance of the cochlea, and of a membrane on which sit rows of hair cells. A second thin membrane lies above the hair cells.');
pq('xp2', 3, 'ear', 'The three small bones in the chain are', 'malleus, incus and stapes', ['hammer, cochlea and oval window', 'incus, cochlea and stapes', 'stapes, round window and malleus'], 'The ossicles are malleus, incus and stapes.');
pq('xp2', 4, 'ear', 'The membrane at the entrance of the cochlea that is moved by the last bone is the', 'oval window', ['round window', 'tectorial membrane', 'Reissner membrane'], 'The stapes presses on the oval window.');
pq('xp2', 4, 'ear', 'The membrane on which the rows of hair cells sit and the thin membrane above them are respectively', 'basilar membrane and tectorial membrane', ['tectorial membrane and basilar membrane', 'oval window and round window', 'Reissner membrane and ear drum'], 'The organ of Corti sits on the basilar membrane; the tectorial membrane lies above the hair cells.');
pass('xp3', 'Passage: an experiment on axon conduction', 'Two axons of the same diameter, one myelinated and one non-myelinated, are stimulated at one end with the same strength. The conduction velocity in the myelinated axon is found to be about 50 times higher. A drug that blocks the Na+ channels at one node of Ranvier of the myelinated axon stops the impulse at that point.');
pq('xp3', 3, 'conduction', 'The higher velocity in the myelinated axon is due to', 'saltatory conduction between nodes', ['a higher resting potential', 'a larger number of synapses', 'continuous depolarisation along the whole membrane'], 'The impulse jumps from one node of Ranvier to the next, which is faster than point-by-point conduction.');
pq('xp3', 4, 'conduction', 'The impulse stops at the blocked node because', 'the inward Na+ current at that node cannot depolarise the node', ['K+ leaves the axon too fast', 'the myelin dissolves', 'the synapse closes'], 'Depolarisation at the node by Na+ entry is needed to excite the next node; if it is blocked, the local current does not reach threshold there.');
pq('xp3', 4, 'conduction', 'In the myelinated axon, the Na+ channels are mainly located at', 'the nodes of Ranvier', ['the myelin sheath', 'the synaptic vesicles', 'the cell body only'], 'Myelin insulates the internodes; the ion exchange takes place at the nodes.');

// ---- Level 5
mc(5, 'eye', 'Which of these structures is NOT crossed by light on its path from outside to the photoreceptors?', 'The choroid', ['The cornea', 'The vitreous humor', 'The ganglion cell layer'], 'Light passes the cornea, aqueous humor, lens and vitreous humor, and enters the retina through its inner layers (ganglion and bipolar cells) to reach the photoreceptors. The choroid lies behind the retina.', 'The choroid is on the outer side of the retina.');
mc(5, 'eye', 'A patient has a lesion that destroys only the ganglion cells of the retina in one eye. What is expected?', 'Photoreceptors still absorb light but the signal does not leave the eye in the optic nerve', ['Photoreceptors are unable to absorb light', 'Light cannot enter the eye', 'The signals pass to the brain through the choroid'], 'Ganglion cell axons form the optic nerve. Photoreceptors still respond, but the signals cannot be sent.');
mc(5, 'eye', 'Which of the following is a correct pair?', 'Iodopsin : cones', ['Rhodopsin : cones', 'Iodopsin : rods', 'Rhodopsin : the lens'], 'Rods contain rhodopsin (visual purple); cones contain iodopsin.');
mc(5, 'eye', 'Which of these is NOT correct for the eye?', 'The lens is held by the suspensory ligaments attached to the sclera', ['The lens separates the aqueous and vitreous chambers', 'The iris is derived from the middle layer', 'The cornea is part of the outer layer'], 'The ligaments of the lens attach to the ciliary body, which forms from the middle layer, not to the sclera.');
mc(5, 'ear', 'Which statement regarding the fluids of the inner ear is correct?', 'Endolymph is inside the membranous labyrinth, which is surrounded by perilymph in the bony labyrinth', ['Perilymph is inside the membranous labyrinth, surrounded by endolymph', 'Both fluids mix freely through the round window', 'The inner ear is filled with air'], 'The membranous labyrinth holds endolymph. The space between the bony and membranous labyrinths holds perilymph.');
mc(5, 'ear', 'During a rapid ascent in an aircraft a passenger feels pressure in the ear and swallows to relieve it. Which structure is involved in this relief?', 'The Eustachian tube', ['The round window', 'The organ of Corti', 'The crista ampullaris'], 'Swallowing opens the Eustachian tube, which connects the middle ear and pharynx and equalises pressure.');
mc(5, 'ear', 'Which of these correctly distinguishes the cochlea from the vestibular apparatus?', 'The cochlea contains the organ of Corti (hearing); the vestibular apparatus contains crista and macula (balance)', ['The cochlea contains crista and macula; the vestibular apparatus contains the organ of Corti', 'Both contain only perilymph', 'Both are in the middle ear'], 'These are two parts of the inner ear with different receptors.');
mc(5, 'neural system', 'Which statement about the cerebral cortex is correct?', 'It is grey matter with motor, sensory and association areas, and its inner part has myelinated fibres (white matter)', ['It is white matter with only motor areas', 'It is the seat of respiration', 'It has no sensory areas'], 'The cerebral cortex is grey (cell bodies); the inner layers of the hemispheres have myelinated nerve fibres, giving a white appearance.');
mc(5, 'impulse', 'The membrane potential of a neuron is -70 mV at rest. After a stimulus the potential reaches +30 mV at the peak. The change in potential, in mV, is', '100', ['40', '70', '30'], '+30 - (-70) = 100 mV.', 'Subtract the signed values.');
mc(5, 'synapse', 'Which feature distinguishes the chemical synapse from the electrical synapse?', 'A synaptic cleft separating the pre- and postsynaptic membranes with transmitter release', ['Direct passage of impulse between neurons through gap junctions', 'Faster transmission without delay', 'Bidirectional transmission'], 'At an electrical synapse the membranes are in very close contact and current flows directly; at a chemical synapse a neurotransmitter crosses the cleft.');
asr(5, 'ear', 'Hair cells of the organ of Corti are stimulated when the basilar membrane moves.', 'Their stereocilia bend against the tectorial membrane.', 0, 'Stereocilia project from the apical end of hair cells and touch the tectorial membrane. When the basilar membrane moves, they bend and generate impulses. R explains A.');
asr(5, 'neural system', 'An impulse can travel from the CNS to the effector but not backwards across a chemical synapse.', 'Neurotransmitters are present only in the presynaptic terminal and receptors only on the postsynaptic membrane.', 0, 'Because vesicles with transmitter are in the pre-synaptic terminal and receptors are postsynaptic, transmission is one-way. R explains A.');
stm(5, 'ear', 'Hair cells have stereocilia on their apical part.', 'The basal ends of hair cells are in close contact with afferent nerve fibres.', 0, 'Both correct.');
stm(5, 'eye', 'In the retina the photoreceptors are the innermost layer, next to the vitreous humor.', 'The ganglion cell layer is the outermost layer, next to the choroid.', 1, 'Both are wrong. The ganglion cell layer is innermost and the photoreceptors are outermost.', 'Do not reverse the order.');
hm(5, 'ear', 'Consider these statements about the human ear. (1) Cochlea is coiled. (2) The utricle has a macula. (3) The organ of Corti has hair cells. (4) The tectorial membrane lies below the hair cells. How many are correct?', 'Only three', ['Only two', 'All four', 'Only one'], '(1), (2), (3) are correct. (4) is wrong: the tectorial membrane lies above the hair cells; the basilar membrane lies below.');
hm(5, 'neural system', 'Consider these statements. (1) Hypothalamus regulates body temperature. (2) Cerebellum has a convoluted surface. (3) Medulla is part of the brain stem. (4) Corpus callosum connects the thalamus with the hypothalamus. How many are correct?', 'Only three', ['Only two', 'All four', 'Only one'], '(1), (2) and (3) are correct. (4) is wrong: the corpus callosum connects the two cerebral hemispheres.');
match(5, 'eye and ear', 'xm8', 'Fluid or structure and location', ['A. Aqueous humor', 'B. Vitreous humor', 'C. Endolymph', 'D. Perilymph'], ['p. Between cornea and lens', 'q. Between lens and retina', 'r. Inside the membranous labyrinth', 's. Between the bony and membranous labyrinths'], 'A-p, B-q, C-r, D-s', ['A-q, B-p, C-r, D-s', 'A-p, B-q, C-s, D-r', 'A-r, B-q, C-p, D-s'], 'Aqueous humor: front chamber. Vitreous humor: behind the lens. Endolymph: membranous labyrinth. Perilymph: around it.');
match(5, 'ear', 'xm9', 'Path of sound in the ear: structure and the next structure or role', ['A. Tympanic membrane', 'B. Incus', 'C. Oval window', 'D. Round window'], ['p. Vibrates first on receiving the sound waves', 'q. Joins the malleus and stapes', 'r. Opening between the middle ear and scala vestibuli', 's. Opening between the middle ear and scala tympani'], 'A-p, B-q, C-r, D-s', ['A-q, B-p, C-r, D-s', 'A-p, B-q, C-s, D-r', 'A-r, B-q, C-p, D-s'], 'The drum receives sound; the incus links the other two bones; the oval window leads to the scala vestibuli; the round window leads to the scala tympani.');
match(4, 'neuron structure', 'xm10', 'Type of neuron and where it is found', ['A. Multipolar', 'B. Bipolar', 'C. Unipolar', 'D. Afferent'], ['p. Cerebral cortex', 'q. Retina of the eye', 'r. Usually in the embryonic stage', 's. Carries impulses from tissues to the CNS'], 'A-p, B-q, C-r, D-s', ['A-q, B-p, C-r, D-s', 'A-p, B-q, C-s, D-r', 'A-r, B-q, C-p, D-s'], 'Multipolar neurons are in the cerebral cortex; bipolar in the retina; unipolar usually in the embryo; afferent fibres carry impulses to the CNS.');

